      { id = 914, faction = "Horde", level = 22, minLevel = 10, name = { ko = "송곳니의 드루이드 우두머리", en = "Leaders of the Fang" }, giver = { ko = "코브란, 아나콘드라, 피타스, 서펜티스의 보석을 모아 썬더 블러프에 있는 나라 와일드메인에게 돌아가야 합니다.", en = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff." } },
      { id = 1486, level = 17, minLevel = 13, name = { ko = "돌연변이 통가죽", en = "Deviate Hides" }, giver = { ko = "통곡의 동굴에 있는 날팍이 돌연변이 통가죽 20개를 가져다 달라고 부탁했습니다.", en = "Nalpak in the Wailing Caverns wants 20 Deviate Hides." } },
      { id = 959, level = 18, minLevel = 14, name = { ko = "99년 묵은 와인", en = "Trouble at the Docks" }, giver = { ko = "톱니항에 있는 기중기 기사 비글퍼즈가 통곡의 동굴에 숨어 있는 광기의 매글리시에게서 99년 숙성된 포트 와인을 되찾아 달라고 부탁했습니다.", en = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns." } },
      { id = 1491, level = 18, minLevel = 13, name = { ko = "영리해지는 음료", en = "Smart Drinks" }, giver = { ko = "톱니항에 있는 메보크 미지릭스에게 통곡의 정수 6병을 가져가야 합니다.", en = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet." } },
      { id = 1487, level = 21, minLevel = 15, name = { ko = "돌연변이 짐승 섬멸", en = "Deviate Eradication" }, giver = { ko = "통곡의 동굴에 있는 에브루가 돌연변이 약탈자랩터 7마리, 돌연변이 독사 7마리, 돌연변이 늪괴물 7마리, 돌연변이 송곳니천둥매 7마리를 처치해 달라고 부탁했습니다.", en = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs." } },
      { id = 6981, level = 26, minLevel = 15, name = { ko = "빛나는 조각", en = "The Glowing Shard" }, giver = { ko = "톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오. 그에게 지시를 받아, 빛나는 조각을 전달해야 합니다.", en = "Travel to Ratchet to find someone that can tell you more about the glowing shard. Then, deliver the shard as you are directed." } },
    },
    trash = { 10413 },
    trashGroups = {
      { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 10413 }, from = { [10413] = { { n = { ko = "송곳니의 드루이드", en = "Druid of the Fang" }, r = 2.34 } } } },
    },
    notes = { { ko = "송곳니의 드루이드는 치유의 손길을 씁니다. 차단을 나눠 맡으세요.", en = "Fanglords heal: assign interrupts." }, { ko = "층이 겹친 동굴입니다. 함부로 뛰어내리면 돌아오기 어렵습니다.", en = "Layered caves: jumping down can split the group." }, { ko = "랩터는 체력이 줄면 주변을 부릅니다. 주변을 비우고 잡으세요.", en = "Raptors call help at low health; clear around first." } },
  },
  {
    key = "dm", slug = "deadmines", levels = "17-26",
    name = { ko = "죽음의 폐광", en = "The Deadmines", de = "Todesminen", fr = "Mortemines", es = "Minas de la Muerte", ru = "Мертвые копи", zhCN = "死亡矿井", zhTW = "死亡礦坑" },
    instanceIDs = { 36 }, nameMatch = { "죽음의 폐광", "Deadmines", "Todesminen", "Mortemines", "Minas de la Muerte", "Мертвые копи", "死亡矿井", "死亡礦坑" },
    entrance = { map = 1436, x = 38.2, y = 77.5, zone = { ko = "서부 몰락지대 달빛시내 마을 광산 안쪽", en = "Inside the mine at Moonbrook, Westfall" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 644 }, model = 14403, name = { ko = "라크조르", en = "Rhahk'Zor" }, loot = { 273289, 872, 5187 }, tip = { ko = "입구 갱도 끝 첫 문을 지키는 오우거입니다. 곁의 데피아즈단 보초부터 정리하고, 라크조르의 격돌로 탱커가 잠깐 기절하는 동안은 딜을 늦추세요. 잡으면 문이 열립니다.", en = "The ogre guarding the first door. Deal with the Defias Watchmen first; Rhahk'Zor Slam stuns the tank briefly, so ease off damage. Killing him opens the door." } },
      { id = "s2", n = "2", kind = "rare", optional = true, npc = { 3586 }, model = 556, name = { ko = "광부 존슨", en = "Miner Johnson" }, loot = { 5443, 5444 }, tip = { ko = "옆길 작은 방에 가끔 있는 희귀 정예입니다. 방어구 관통으로 탱커 방어도를 깎으니 잡으려면 둘레 광부부터 정리하세요. 그냥 지나가도 됩니다.", en = "Rare elite sometimes found in a small side room. Pierce Armor lowers the tank's armor; clear the miners around him first if you fight him. Safe to skip." } },
      { id = "s3", n = "3", kind = "boss", npc = { 643, 642 }, model = 7125, name = { ko = "스니드", en = "Sneed" }, quest = true, loot = { 273293, 5194, 5195, 273092, 1937, 2169, 285292 }, quests = { 2040, 1654 }, tip = { ko = "스니드의 벌목기에 탄 채 덤빕니다. 공포에 질린 사람이 다른 무리를 끌지 않게 방을 미리 비우고, 벌목기를 부수면 튀어나오는 스니드는 무장 해제를 씁니다.", en = "Comes in Sneed's Shredder. Clear the room first so Terrify doesn't send anyone into packs; break the Shredder and Sneed pops out using Disarm." } },
      { id = "s4", n = "4", kind = "boss", npc = { 1763 }, model = 7124, name = { ko = "길니드", en = "Gilnid" }, quest = true, loot = { 273297, 1156, 5199, 273086 }, quests = { 2040 }, tip = { ko = "고블린 제련소에서 일꾼들과 함께 싸웁니다. 둘레 제련공을 먼저 정리하고, 용해된 금속은 화염 피해와 함께 공격·이동을 느리게 하니 맞은 사람을 챙기세요.", en = "In the goblin foundry with his workers. Clear the smelters first; Molten Metal burns and slows attacks and movement, so watch whoever gets hit." } },
      { id = "s5", n = "5", kind = "object", name = { ko = "데피아즈단 화약", en = "Defias Gunpowder" }, quest = true, quests = { 92753 }, tip = { ko = "'죽음의 폐광 파괴 작전'(얼라이언스)은 화약 더미가 쌓인 제련소 옆, 숨겨진 가열로에 강력 파괴 폭발물을 놓으면 됩니다.", en = "For Destruction in Deadmines (Alliance), set the explosives at the hidden forge beside the foundry, near this gunpowder pile." } },
      { id = "s6", n = "6", kind = "boss", npc = { 646 }, model = 2026, name = { ko = "미스터 스마이트", en = "Mr. Smite" }, loot = { 284715, 7230, 5192, 5196 }, tip = { ko = "숨겨진 배의 첫 우두머리로, 곁의 데피아즈단 검은자객 둘을 먼저 잡으세요. 체력이 줄 때마다 스마이트의 발구르기로 모두를 기절시키고 상자에서 무기를 바꾸니, 풀리면 다시 모여 붙습니다.", en = "First boss on the hidden ship; kill his two Defias Blackguards first. At health thresholds Smite Stomp stuns everyone while he swaps weapons at his chest; regroup once it ends." } },
      { id = "s8", n = "8", kind = "boss", npc = { 647 }, model = 7113, name = { ko = "선장 그린스킨", en = "Captain Greenskin" }, loot = { 5201, 10403, 5200 }, tip = { ko = "해적 몇과 함께 덤빕니다. 회전베기가 곁에 선 사람까지 베니 근접은 선장 등 뒤에 서고, 독 묻은 작살의 독은 바로 해제하세요.", en = "Fights with a few pirates. Cleave also hits whoever stands next to the target, so melee stay behind him; cure the Poisoned Harpoon poison quickly." } },
      { id = "s7", n = "7", kind = "boss", npc = { 645 }, model = 1305, name = { ko = "쿠키", en = "Cookie" }, loot = { 273298, 5198, 5197, 273102, 8490 }, tip = { ko = "갑판 아래 주방의 요리사입니다. 쿠키의 요리로 생명력을 채우니 꼭 끊고, 산성 물질 끼얹기의 지속 피해는 힐러가 받아 냅니다.", en = "The cook in the galley below deck. Always interrupt Cookie's Cooking, his self-heal; healers cover the Acid Splash damage over time." } },
      { id = "s9", n = "9", kind = "boss", npc = { 639 }, model = 2029, name = { ko = "에드윈 밴클리프", en = "Edwin VanCleef" }, quest = true, loot = { 5193, 5202, 10399, 5191, 2874 }, quests = { 166, 373 }, tip = { ko = "배 뒤쪽 윗갑판에서 검은자객들과 함께 기다립니다. 체력이 줄면 밴클리프의 동맹으로 검은자객을 더 부르니 묶거나 먼저 잡고, 떨군 부치지 않은 편지를 꼭 챙기세요.", en = "Waits on the upper deck aft with Defias Blackguards. VanCleef's Allies brings more as his health drops; control or kill them first, and grab An Unsent Letter." } },
    },
    quests = {
      { id = 214, faction = "Alliance", level = 17, minLevel = 14, name = { ko = "붉은 비단 복면", en = "Red Silk Bandanas" }, giver = { ko = "감시의 언덕 탑의 정찰병 리엘이 붉은 비단 복면 10개를 가져다 달라고 부탁했습니다.", en = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas." } },
      { id = 168, faction = "Alliance", level = 18, minLevel = 14, name = { ko = "기억을 더듬어...", en = "Collecting Memories" }, giver = { ko = "스톰윈드에 있는 빌더 시슬네틀에게 광부 조합의 명함 4장을 가져가야 합니다.", en = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind." } },
      { id = 92753, faction = "Alliance", level = 18, minLevel = 9, name = { ko = "죽음의 폐광 파괴 작전", en = "Destruction in Deadmines" }, giver = { ko = "죽음의 폐광에서 숨겨진 가열로를 찾아 주변에 강력 파괴 폭발물을 설치해야 합니다. 그런 다음 죽음의 폐광 출구에서 알바 페어문을 만나야 합니다.", en = "Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit." } },
      { id = 2040, faction = "Alliance", level = 20, minLevel = 15, name = { ko = "지하 공격", en = "Underground Assault" }, giver = { ko = "죽음의 폐광에서 노암 톱니구동장치를 찾아 스톰윈드에 있는 쇼니에게 가져가야 합니다.", en = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind." } },
      { id = 167, faction = "Alliance", level = 20, minLevel = 15, name = { ko = "형제여...", en = "Oh Brother..." }, giver = { ko = "스톰윈드에 있는 빌더 시슬네틀에게 시슬네틀의 배지를 가져가야 합니다.", en = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind." } },
      { id = 166, faction = "Alliance", level = 22, minLevel = 14, name = { ko = "데피아즈단", en = "The Defias Brotherhood" }, giver = { ko = "에드윈 밴클리프를 처치하고 그 증거로 그의 가면을 그라이언 스타우트맨틀에게 가져가야 합니다.", en = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle." } },
      { id = 373, faction = "Alliance", level = 22, minLevel = 16, name = { ko = "부치지 않은 편지", en = "The Unsent Letter" }, giver = { ko = "스톰윈드에 있는 도시 건축가 바로스 알렉스턴에게 편지를 전달해야 합니다.", en = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind." } },
      { id = 1654, faction = "Alliance", level = 22, minLevel = 20, name = { ko = "정의의 시험", en = "The Test of Righteousness" }, giver = { ko = "흰돌참나무 재목은 이곳 고블린 목공이 떨굽니다. 재료 넷을 아이언포지의 조던 스틸웰에게(성기사).", en = "Goblin Woodcarvers here drop the Whitestone Oak Lumber; bring all four items to Jordan Stilwell in Ironforge (Paladin)." } },
      { id = 95036, faction = "Horde", level = 25, minLevel = 20, name = { ko = "달빛이 입 맞춘 칼날", en = "A Moon-Kissed Blade" }, giver = { ko = "언데드 전용. 공동묘지의 트레반 롤과 대화한 뒤 재료를 모아 갑니다. 흰돌참나무 재목은 이곳 고블린 목공이 떨굽니다.", en = "Undead only. After talking to Trevan Roll in the graveyard, bring him the materials; Whitestone Oak Lumber drops from the Goblin Woodcarvers here." } },
    },
