  {
    key = "rol", slug = "ruins-of-lordaeron", levels = "15-22",
    name = { ko = "로데론의 폐허", en = "Ruins of Lordaeron", de = "Ruinen von Lordaeron", fr = "Ruines de Lordaeron", es = "Ruinas de Lordaeron", ru = "Руины Лордерона", zhCN = "洛丹伦废墟", zhTW = "羅德隆廢墟" },
    instanceIDs = { 2999 }, nameMatch = { "로데론의 폐허", "Ruins of Lordaeron", "Ruinen von Lordaeron", "Ruines de Lordaeron", "Ruinas de Lordaeron", "Руины Лордерона", "洛丹伦废墟", "羅德隆廢墟" },
    entrance = { map = 1420, x = 63.3, y = 67.5, zone = { ko = "티리스팔 숲 로데론 폐허 안뜰 동쪽", en = "Eastern courtyard of the Lordaeron ruins, Tirisfal Glades" } },
    steps = {
      { id = "s1", n = "1", kind = "npc", npc = { 265701 }, optional = true, name = { ko = "대장 트루먼", en = "Captain Truman" }, quest = true, quests = { 95250 }, tip = { ko = "입구를 나와 바로 왼쪽(북쪽) 벽돌 길의 NPC. 얼라이언스 '흉측한 생명체'를 주고받습니다(남작의 머리).", en = "Just left (north) of the entrance on the brick path. Alliance quest Abominable Creatures (the Baron's head)." } },
      { id = "s2", n = "2", kind = "boss", npc = { 250483 }, name = { ko = "쇠퇴송곳니", en = "Witherfang" }, aliases = { "Welkzahn", "Croc-Flétri", "Colmimarchito", "Сухожвал", "枯牙", "枯萎之牙" }, quest = true, loot = { 271203, 271201, 271202 }, quests = { 95216 }, tip = { ko = "동쪽 거미 구역 넓은 방. 쫄 셋을 달고 긴 복도를 순찰하니, 자리를 비운 사이 남은 무리를 치우세요. 탱커에게 착취의 독. 호드 '새로운 역병'의 균주.", en = "Big room in the east spider area. Patrols the hallway with three adds; clear while she's away. Leech Poison on the tank. Horde quest item." } },
      { id = "s3", n = "3", kind = "boss", npc = { 250660 }, name = { ko = "도살자(남작)", en = "The Butcher(The Baron)" }, aliases = { "도살자", "The Butcher", "Der Schlächter", "Le Boucher", "El Carnicero", "Мясник", "屠夫" }, quest = true, loot = { 271204, 271205, 271206 }, quests = { 95250, 97288 }, tip = { ko = "게임 안 이름은 '남작'. 거대한 누더기골렘이라 한 방이 아주 셉니다. 탱커 기절·띄우기·전방 베기. 부탱커를 정해 두고 딜러는 어그로 조절.", en = "Shown as The Baron in game. Huge abomination: Knockout stuns the tank, knock-up, cleave. Assign an off-tank; DPS watch threat." } },
      { id = "s8", n = "4", kind = "rare", optional = true, npc = { 255699 }, name = { ko = "로데론 부대장", en = "Lordaeron Captain" }, aliases = { "Hauptmann von Lordaeron", "Capitaine de Lordaeron", "Capitán de Lordaeron", "Лордеронский капитан", "洛丹伦上尉", "羅德隆隊長" }, loot = { 6641, 6642 }, tip = { ko = "희귀 정예. 다른 우두머리를 다 잡으면 서쪽에 나올 때가 있고 넓게 순찰합니다. 얼라이언스에게는 우호적이라 호드만 잡을 수 있습니다.", en = "Rare elite; may appear in the west once the other bosses are dead, on a long patrol. Friendly to the Alliance: Horde only." } },
      { id = "s7", n = "5", kind = "boss", npc = { 256035 }, optional = true, name = { ko = "비열한 빅토르", en = "Viktor the Vile" }, aliases = { "Viktor der Üble", "Viktor le Vil", "Viktor el Abyecto", "Виктор Вероломный", "邪恶的维克多", "邪惡的維多" }, loot = { 271211, 271212, 271218 }, tip = { ko = "남작 다음 남쪽 길을 따라 서쪽 끝 둥근 탑 옆 벽난로로 갑니다. 불을 붙이면 적이 다섯 차례 몰려오고 여섯 번째에 빅토르가 나옵니다. 연속 공세와 강한 근접·착취의 독에 대비해 체력과 마나를 채우세요.", en = "After the Baron, follow the southern road west to the fireplace by the round tower. Light it: five waves, then Viktor as the sixth. Top up health/mana for continuous waves, hard melee and Leech Poison." } },
      { id = "s4", n = "6", kind = "boss", npc = { 250631 }, optional = true, name = { ko = "버려진 자", en = "The Abandoned" }, aliases = { "Der Verlassene", "L’Abandonné", "El Abandonado", "Покинутый", "被遗弃者", "被棄者" }, loot = { 271207, 271208, 271216 }, tip = { ko = "빅토르 벽난로 북동쪽 육각 지붕 건물의 통로를 지나 북쪽 문간으로 갑니다. 문간에 들어서면 세 차례 공세 뒤 네 번째에 나타납니다. 비선공 유령 시민은 건드리지 마세요. 얼음 회오리와 생명력 흡수(차단 가능).", en = "From the fireplace, pass through the hexagon-roofed building to the northeast and go north to the doorway. Three waves, then the Abandoned on the fourth. Leave non-aggressive Ghostly Citizens alone. Frost Nova and interruptible Life Drain." } },
      { id = "s5", n = "7", kind = "boss", npc = { 256097 }, name = { ko = "비요크", en = "Bjork" }, aliases = { "Бьорк", "比约克", "布喬克" }, loot = { 271209, 271217, 271210 }, tip = { ko = "버려진 자 문간에서 계속 북쪽으로 가면 시장 거리 북서쪽 안개 구역입니다. 거대한 트롤 언데드가 순찰하니 해골·구울 무리를 먼저 정리하세요. 3초 대마법 보호막 동안 시전을 멈추고, 넉백에 대비해 벽을 등지세요.", en = "Continue north from the Abandoned doorway into foggy northwest Market Street. Clear skeletal mages and ghouls while avoiding the roaming undead troll. Hold spells during the 3-second Anti-Magic Shell; tank against a wall for knockback." } },
      { id = "s6", n = "8", kind = "boss", npc = { 250657 }, name = { ko = "라스마엘", en = "Rath'mael" }, aliases = { "Rath’mael", "Рат'маэль", "拉斯玛尔", "拉斯梅爾" }, quest = true, loot = { 271213, 271214, 271215, 273085, 273103 }, quests = { 92422 }, tip = { ko = "비요크 다음 남은 구울을 정리하며 연못 동쪽을 따라 남쪽 막다른 곳의 보라색 룬으로 갑니다. 마지막 우두머리를 룬 밖으로 끌어내세요. 불기둥은 차단 순서를 정하고 놓치면 즉시 피하세요.", en = "After Bjork, clear ghouls down the east side of the pools and go south to the purple rune in the dead end. Pull the final boss off the rune. Rotate interrupts for Flamestrike and dodge missed casts." } },
    },
    quests = {
      { id = 95250, faction = "Alliance", level = 21, minLevel = 15, name = { ko = "흉측한 생명체", en = "Abominable Creatures" }, giver = { ko = "남작을 처치하고 남작의 머리를 대장 트루먼에게.", en = "Kill the Baron; bring the Head of the Baron to Captain Truman." } },
      { id = 92415, faction = "Alliance", level = 22, minLevel = 15, name = { ko = "내가 사랑한다는 걸 기억해", en = "Remember That I Love You" }, giver = { ko = "피로 얼룩진 편지를 스톰윈드에 있는 보육원 원장님 나이팅게일에게 가져가야 합니다.", en = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City." } },
      { id = 95189, faction = "Alliance", level = 22, minLevel = 15, name = { ko = "로데론의 문장", en = "Crest of Lordaeron" }, giver = { ko = "로데론의 문장을 스톰윈드에 있는 귀부인 디나 케네디에게 반환해야 합니다.", en = "Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City." } },
      { id = 95195, faction = "Alliance", level = 22, minLevel = 15, name = { ko = "피투성이 휘장", en = "Bloodied Insignia" }, giver = { ko = "드랍된 피투성이 휘장으로 시작해 10개를 모아 스톰윈드의 장군 마커스 조나단에게", en = "Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City." } },
      { id = 97288, faction = "Horde", level = 21, minLevel = 15, name = { ko = "끝없는 고통", en = "Unending Torment" }, giver = { ko = "흉측한 머리를 언더시티에 있는 누군가에게 전해야 합니다.", en = "Deliver the Abominable Head to someone within the Undercity." } },
      { id = 92401, faction = "Horde", level = 22, minLevel = 15, name = { ko = "두려움에 찬 부탁", en = "A Frightened Request" }, giver = { ko = "로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다.", en = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron." } },
      { id = 92422, faction = "Horde", level = 22, minLevel = 15, name = { ko = "라스마엘의 격노", en = "The Wrath of Rath'mael" }, giver = { ko = "브릴의 죽음경비병 크리스토프를 위해 로데론의 폐허에 있는 라스마엘을 처치해야 합니다.", en = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill." } },
      { id = 95204, faction = "Horde", level = 22, minLevel = 15, name = { ko = "로데론의 문장", en = "Crest of Lordaeron" }, giver = { ko = "던전 안 어딘가에 놓인 로데론의 문장(자리가 고정되지 않음)으로 시작해 언더시티의 오란 스네이크라이스에게", en = "Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity." } },
      { id = 92421, faction = "Horde", level = 22, minLevel = 15, name = { ko = "빛의 정의", en = "Light's Justice" }, giver = { ko = "언더시티에 있는 모빈 라이트베인을 위해 로데론의 폐허에서 온전한 사지 25개를 수집해야 합니다.", en = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity." } },
      { id = 95216, faction = "Horde", level = 22, minLevel = 15, name = { ko = "새로운 역병", en = "The New Plague" }, giver = { ko = "로데론의 폐허에 있는 쇠퇴송곳니에게서 맹독성 균주를 얻어 언더시티에 있는 시어도어 그리프스에게 가져가야 합니다.", en = "Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity." } },
    },
    trash = { 286977, 286978, 286979, 286980, 286981 },
    trashGroups = { { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 286977, 286978, 286979, 286980, 286981 } } },
    notes = { { ko = "추천 순서: 대장 트루먼 → 쇠퇴송곳니 → 남작 → 비열한 빅토르(선택) → 버려진 자(선택) → 비요크 → 라스마엘.", en = "Suggested route: Captain Truman → Witherfang → the Baron → Viktor (optional) → the Abandoned (optional) → Bjork → Rath'mael." }, { ko = "쇠퇴송곳니가 쫄을 데리고 순찰합니다. 경로를 보고 시작하세요.", en = "Witherfang patrols with adds; watch her path." }, { ko = "'로데론의 문장'은 자리가 고정되지 않습니다. 건물 바닥을 살펴보세요.", en = "The Crest of Lordaeron has no fixed spot; check building floors." } },
  },
  {
    key = "sfk", slug = "shadowfang-keep", levels = "20-30",
    name = { ko = "그림자송곳니 성채", en = "Shadowfang Keep", de = "Burg Shadowfang", fr = "Donjon d'Ombrecroc", es = "Castillo de Colmillo Oscuro", ru = "Крепость Темного Клыка", zhCN = "影牙城堡", zhTW = "影牙城堡" },
    instanceIDs = { 33 }, nameMatch = { "그림자송곳니", "Shadowfang", "Burg Shadowfang", "Donjon d'Ombrecroc", "Castillo de Colmillo Oscuro", "Крепость Темного Клыка", "影牙城堡" },
    entrance = { map = 1421, x = 44.7, y = 67.8, zone = { ko = "은빛소나무 숲 그림자송곳니 성채", en = "Shadowfang Keep, Silverpine Forest" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 3914 }, model = 524, name = { ko = "레실고어", en = "Rethilgore" }, quest = true, loot = { 273457, 273456, 5254 }, quests = { 1098 }, tip = { ko = "첫 우두머리. 영혼 흡수로 한 명을 묶고 생명력을 빼앗습니다. 잡은 뒤 옆 감방의 죽음추적자 아다만트(호드)나 마법사 애쉬크롬비(얼라이언스)를 풀어 주면 안뜰 문이 열립니다.", en = "First boss; Soul Drain roots a player and drains health. Afterwards free Deathstalker Adamant (Horde) or Sorcerer Ashcrombe (Alliance) from the cells next door to open the courtyard door." } },
      { id = "s2", n = "2", kind = "npc", optional = true, name = { ko = "죽음추적자 빈센트", en = "Deathstalker Vincent" }, quest = true, quests = { 1098 }, tip = { ko = "'그림자송곳니 성채의 죽음추적자'에서 찾는 두 번째 죽음추적자입니다. 안뜰에 죽은 듯 쓰러져 있는 빈센트에게 말을 걸면 완료됩니다.", en = "The second Deathstalker for Deathstalkers in Shadowfang; he lies as if dead in the courtyard. Talk to him to finish the quest." } },
      { id = "s3", n = "3", kind = "task", name = { ko = "지옥마 · 암흑마", en = "Fel Steed & Shadow Charger" }, loot = { 6341, 932, 251381 }, tip = { ko = "안뜰 마구간의 정예 말 셋. 하나를 건드리면 셋이 함께 오고, 지옥의 발구름으로 주변을 기절시킵니다.", en = "Three elite horses in the stables; pull one and all come. Fel Stomp stuns nearby." } },
      { id = "s4", n = "4", kind = "object", optional = true, name = { ko = "조던의 망치", en = "Jordan's Hammer" }, quest = true, quests = { 1654 }, tip = { ko = "성기사 퀘스트 '정의의 시험'의 조던의 망치가 여기 있습니다.", en = "Jordan's Hammer for the paladin quest The Test of Righteousness." } },
      { id = "s5", n = "5", kind = "boss", npc = { 3886 }, model = 524, name = { ko = "도살자 칼날발톱", en = "Razorclaw the Butcher" }, loot = { 1292, 6226, 6633, 273096 }, tip = { ko = "도살자의 흡수로 체력을 빼앗습니다. 탱커 체력 관리.", en = "Butcher Drain leeches health; keep the tank healed." } },
      { id = "s6", n = "6", kind = "boss", optional = true, npc = { 3887 }, model = 3222, name = { ko = "남작 실버레인", en = "Baron Silverlaine" }, loot = { 273637, 6321, 6323 }, tip = { ko = "암흑의 장막으로 받는 치유가 줄어듭니다. 저주를 해제하세요.", en = "Veil of Shadow cuts healing taken; remove the curse." } },
      { id = "s7", n = "7", kind = "boss", npc = { 4278 }, model = 3223, name = { ko = "사령관 스프링베일", en = "Commander Springvale" }, quest = true, loot = { 273643, 6320, 3191, 273105 }, quests = { 1740 }, tip = { ko = "심판의 망치로 기절시키고 성스러운 빛으로 회복합니다. 치유를 끊으세요.", en = "Stuns with Hammer of Justice and heals with Holy Light; interrupt." } },
      { id = "s8", n = "8", kind = "boss", npc = { 4279 }, model = 522, name = { ko = "눈먼감시자 오도", en = "Odo the Blindwatcher" }, loot = { 273645, 6318, 6319 }, tip = { ko = "체력이 줄 때마다 분노의 포효로 더 세지니 끝으로 갈수록 탱커 치유를 늘리세요. 함께 있는 흡혈박쥐·그림자박쥐는 먼저 잡거나 광역으로 정리합니다.", en = "Howling Rage makes him stronger each time his health drops, so heal the tank harder toward the end. Kill the Blood Seeker and Vile Bat with him first or AoE them." } },
      { id = "s9", n = "9", kind = "boss", npc = { 4274 }, model = 2352, name = { ko = "파멸의 펜루스", en = "Fenrus the Devourer" }, loot = { 273646, 6340, 3230 }, tip = { ko = "맹독액으로 독을 겁니다. 독을 해제하세요.", en = "Toxic Saliva poisons; cure it." } },
      { id = "s10", n = "10", kind = "object", optional = true, name = { ko = "우르의 책", en = "The Book of Ur" }, quest = true, quests = { 1013 }, tip = { ko = "호드 퀘스트 '우르의 책'의 책이 여기 있습니다.", en = "The book for the Horde quest The Book of Ur." } },
      { id = "s11", n = "11", kind = "boss", npc = { 3927 }, model = 11179, name = { ko = "늑대왕 난도스", en = "Wolf Master Nandos" }, loot = { 273647, 3748, 6314 }, tip = { ko = "늑대를 차례로 부릅니다. 쫄을 정리하며 싸우세요.", en = "Summons worgs in turn; handle the adds as they come." } },
      { id = "s12", n = "12", kind = "boss", npc = { 4275 }, model = 2353, name = { ko = "대마법사 아루갈", en = "Archmage Arugal" }, quest = true, loot = { 6324, 6392, 6220 }, quests = { 1014 }, tip = { ko = "공허의 화살·천둥충격, 방 안을 순간이동합니다. 원거리가 계속 따라가며 공격하세요.", en = "Void Bolt, Thundershock, teleports around; ranged keep on him." } },
    },
    quests = {
      { id = 1654, faction = "Alliance", level = 22, minLevel = 20, name = { ko = "정의의 시험", en = "The Test of Righteousness" }, giver = { ko = "조던의 쪽지에 적힌 재료 넷(흰돌참나무 재목·광석 상자·대장장이 망치·코르석)을 아이언포지의 조던 스틸웰에게(성기사).", en = "The four items from Jordan's Weapon Notes to Jordan Stilwell in Ironforge (Paladin)." } },
      { id = 1098, faction = "Horde", level = 25, minLevel = 18, name = { ko = "그림자송곳니 성채의 죽음추적자", en = "Deathstalkers in Shadowfang" }, giver = { ko = "죽음의추적자 아다만트와 죽음의추적자 빈센트를 찾아야 합니다.", en = "Find the Deathstalker Adamant and Deathstalker Vincent." } },
      { id = 1013, faction = "Horde", level = 26, minLevel = 16, name = { ko = "우르의 책", en = "The Book of Ur" }, giver = { ko = "언더시티의 연금술 실험실에 있는 관리인 벨두거에게 우르의 책을 가져가야 합니다.", en = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity." } },
      { id = 1014, faction = "Horde", level = 27, minLevel = 18, name = { ko = "아루갈의 최후", en = "Arugal Must Die" }, giver = { ko = "아루갈을 처치하고 그 증거로 그의 머리카락을 공동묘지에 있는 달라 던위버에게 가져가야 합니다.", en = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher." } },
      { id = 1740, level = 25, minLevel = 20, name = { ko = "소랜루크 수정구", en = "The Orb of Soran'ruk" }, giver = { ko = "소랜루크 조각 3개와 큰 소랜루크 조각 1개를 불모의 땅의 도안 카르한에게(흑마법사).", en = "3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment to Doan Karhan in the Barrens (Warlock)." } },
      { id = 78261, level = 23, minLevel = 1, name = { ko = "젤토스의 뿔", en = "The Horn of Xelthos" }, giver = { ko = "성채에서 젤토스의 뿔을 찾아 장작나무 마을 근처 C의 은닉처에 혼자 가져가기(도적).", en = "Find the Horn of Xelthos in the keep and bring it alone to C's dead drop near Pyrewood Village (rogue)." } },
