    notes = { { ko = "레실고어 다음 감옥에서 진영 NPC를 풀어야 안뜰 문이 열립니다.", en = "Free your faction's prisoner after Rethilgore to open the courtyard." }, { ko = "지도는 4층(안뜰·하층, 상층, 마법사 탑 하층, 마법사 탑 상층)으로 나뉩니다. 연결 표식이나 좌측 상단 층 선택으로 전환하세요.", en = "Four map floors; switch floors via the top-left picker or clickable floor links." } },
  },
  {
    key = "bfd", slug = "blackfathom-deeps", levels = "24-32",
    name = { ko = "검은심연의 나락", en = "Blackfathom Deeps", de = "Blackfathom-Tiefe", fr = "Profondeurs de Brassenoire", es = "Cavernas de Brazanegra", ru = "Непроглядная Пучина", zhCN = "黑暗深渊", zhTW = "黑澗深淵" },
    instanceIDs = { 48 }, nameMatch = { "검은심연", "Blackfathom", "Blackfathom-Tiefe", "Profondeurs de Brassenoire", "Cavernas de Brazanegra", "Непроглядная Пучина", "黑暗深渊", "黑澗深淵" },
    entrance = { map = 1440, x = 16.5, y = 11.0, zone = { ko = "잿빛 골짜기 조람 해안의 물에 잠긴 사원", en = "Sunken temple on the Zoram Strand, Ashenvale" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 4887 }, model = 5027, name = { ko = "가무라", en = "Ghamoo-ra" }, loot = { 273839, 6907, 6908 }, tip = { ko = "첫 우두머리인 거대 거북입니다. 방어도가 높아 주문 공격이 잘 들어가고, 밟아 뭉개기가 곁에 붙은 모두를 치니 근접은 체력을 보세요.", en = "The giant turtle, first boss. His armor is high, so spells do well; Trample hits everyone next to him, so melee watch their health." } },
      { id = "s2", n = "2", kind = "object", name = { ko = "로르갈리스 초본", en = "Lorgalis Manuscript" }, quest = true, quests = { 971 }, tip = { ko = "얼라이언스 퀘스트 '심연의 지식'의 책이 바닥에 놓여 있습니다. 집어서 아이언포지의 게릭 본그립에게 가져가세요.", en = "The book for the Alliance quest Knowledge in the Deeps lies on the floor; take it to Gerrig Bonegrip in Ironforge." } },
      { id = "s3", n = "3", kind = "boss", npc = { 4831 }, model = 4979, name = { ko = "여왕 사레베스", en = "Lady Sarevess" }, loot = { 888, 3078, 11121 }, tip = { ko = "곁의 나가부터 잡으세요. 갈래 번개가 정면 부채꼴로 뻗으니 탱커는 사레베스를 파티 반대쪽으로 돌리고, 나머지는 옆이나 뒤에 섭니다.", en = "Kill the nagas with her first. Forked Lightning hits a cone in front of her, so the tank turns her away and everyone else stands at her side or back." } },
      { id = "s4", n = "4", kind = "npc", name = { ko = "은빛경비병 타엘리드", en = "Argent Guard Thaelrid" }, quest = true, quests = { 1198, 1200, 6561 }, tip = { ko = "말을 걸면 '타엘리드 찾기'가 끝나고, 황혼의 군주 켈리스를 잡는 '검은심연의 음모'를 받습니다(양 진영).", en = "Talk to him to finish In Search of Thaelrid and pick up Blackfathom Villainy, the Kelris kill quest (both factions)." } },
      { id = "s5", n = "5", kind = "boss", npc = { 6243 }, model = 1773, name = { ko = "겔리하스트", en = "Gelihast" }, loot = { 273840, 6906, 6905, 1470, 273141 }, tip = { ko = "멀록 무리 한가운데에 있습니다. 둘레 멀록을 한두 마리씩 끌어 먼저 잡고 붙으세요. 그물에 걸리면 잠시 움직일 수 없습니다.", en = "Sits among a crowd of murlocs. Pull the murlocs around him a couple at a time first. Net roots you for a few seconds." } },
      { id = "s6", n = "6", kind = "boss", optional = true, npc = { 12902 }, model = 12822, name = { ko = "로구스 제트", en = "Lorgus Jett" }, quest = true, loot = { 273842, 273843, 273841 }, quests = { 6565 }, tip = { ko = "지도의 옅은 원 가운데 한 곳에 나타납니다. 번개 화살은 끊고, 공격하는 사람을 치는 번개 보호막은 정화나 마법 무효화로 벗기세요. 호드 '고대 신들에 대한 충성' 대상입니다.", en = "Appears at one of the faint circles on the map. Interrupt Lightning Bolt and purge his Lightning Shield, which zaps attackers. Target of the Horde quest Allegiance to the Old Gods." } },
      { id = "s7", n = "7", kind = "boss", npc = { 4830 }, model = 1816, name = { ko = "늙은 세라키스", en = "Old Serra'kis" }, from = { 323, 407 }, loot = { 6901, 6902, 6904 }, tip = { ko = "물속에서 싸우는 상어입니다. 특별한 기술은 없으니 수중 호흡을 걸고 숨이 떨어지기 전에 빨리 잡으세요.", en = "A shark fought underwater. He has no special abilities: use water breathing and kill him before your breath runs out." } },
      { id = "s8", n = "8", kind = "npc", optional = true, npc = { 12876 }, model = 110, name = { ko = "군주 아쿠아니스", en = "Baron Aquanis" }, quest = true, loot = { 16782 }, quests = { 6921, 6922 }, tip = { ko = "호드 '폐허 사이로'를 하면 심연의 돌에서 심연의 핵을 꺼낼 때 나타나는 물의 정령입니다. 얼음 화살은 끊고, 잡으면 '군주 아쿠아니스'를 시작하는 이상한 물구슬을 떨굽니다.", en = "On the Horde quest Amongst the Ruins, taking the Fathom Core from the Fathom Stone summons him. Interrupt Frostbolt; he drops the Strange Water Globe that starts Baron Aquanis." } },
      { id = "s9", n = "9", kind = "boss", npc = { 4832 }, model = 4939, name = { ko = "황혼의 군주 켈리스", en = "Twilight Lord Kelris" }, quest = true, from = { 154, 366 }, loot = { 273846, 1155, 6903 }, quests = { 1199, 1200, 6561 }, tip = { ko = "아쿠마이에게 가는 길목의 제단 방을 지킵니다. 방 안 무리를 입구 벽 뒤로 끌어 먼저 잡고, 정신 분열은 끊고 수면에 빠진 사람은 마법 해제로 깨우세요.", en = "Guards the altar room on the way to Aku'mai. Pull the room's packs behind the entrance wall first, interrupt Mind Blast and dispel Sleep." } },
      { id = "s10", n = "10", kind = "task", name = { ko = "조각상 둘레 화로 정리", en = "Clear the braziers around the statue" }, tip = { ko = "켈리스를 잡은 뒤 조각상 둘레의 아쿠마이의 불 네 개에 하나씩 불을 붙이세요. 붙일 때마다 적이 몰려오니 다 잡고 다음으로 넘어가면 아쿠마이로 가는 문이 열립니다.", en = "After Kelris, light the four Fires of Aku'mai around the statue one at a time. Each one brings a wave of adds; finish it before the next, and the door to Aku'mai opens." } },
      { id = "s11", n = "11", kind = "boss", npc = { 4829 }, model = 2837, name = { ko = "아쿠마이", en = "Aku'mai" }, quest = true, loot = { 6911, 6910, 6909 }, quests = { 6563 }, tip = { ko = "가장 안쪽 방의 히드라입니다. 독구름이 깔리면 바로 빠져나오고, 체력이 낮을 때 광적인 분노로 공격이 빨라지니 힐러는 탱커에 집중하세요.", en = "The hydra in the last chamber. Step out of Poison Cloud right away; at low health Frenzied Rage speeds up its attacks, so healers focus the tank." } },
    },
    quests = {
      { id = 971, faction = "Alliance", level = 23, minLevel = 18, name = { ko = "심연의 지식", en = "Knowledge in the Deeps" }, giver = { ko = "아이언포지, 쓸쓸한 뒷골목에 있는 게릭 본그립에게 로르갈리스 초본을 가져가야 합니다.", en = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge." } },
      { id = 1275, faction = "Alliance", level = 24, minLevel = 18, name = { ko = "타락에 대한 연구", en = "Researching the Corruption" }, giver = { ko = "아우버다인에 있는 게르샬라 나이트위스퍼가 변이된 뇌간 8개를 가져다 달라고 부탁했습니다.", en = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems." } },
      { id = 1198, faction = "Alliance", level = 24, minLevel = 18, name = { ko = "타엘리드 찾기", en = "In Search of Thaelrid" }, giver = { ko = "검은심연의 나락에서 은빛경비병 타엘리드를 찾아야 합니다.", en = "Seek out Argent Guard Thaelrid in Blackfathom Deeps." } },
      { id = 1200, faction = "Alliance", level = 27, minLevel = 18, name = { ko = "검은심연의 음모", en = "Blackfathom Villainy" }, giver = { ko = "황혼의 군주 켈리스를 처치하고 그 증거로 머리카락을 다르나서스에 있는 새벽감시자에게 가져가야 합니다.", en = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus." } },
      { id = 1199, faction = "Alliance", level = 25, minLevel = 20, name = { ko = "황혼의망치단의 몰락", en = "Twilight Falls" }, giver = { ko = "다르나서스에 있는 은빛경비병 마나도스에게 황혼의 펜던트 10개를 가져가야 합니다.", en = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus." } },
      { id = 6564, faction = "Horde", level = 22, minLevel = 17, name = { ko = "고대 신들에 대한 충성", en = "Allegiance to the Old Gods" }, giver = { ko = "축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오.", en = "Bring the Damp Note to Je'neu Sancrea in Ashenvale." } },
      { id = 6565, faction = "Horde", level = 26, minLevel = 17, name = { ko = "고대 신들에 대한 충성", en = "Allegiance to the Old Gods" }, giver = { ko = "검은심연의 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.", en = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale." } },
      { id = 6563, faction = "Horde", level = 22, minLevel = 17, name = { ko = "아쿠마이의 정수", en = "The Essence of Aku'Mai" }, giver = { ko = "잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다.", en = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale." } },
      { id = 6561, faction = "Horde", level = 27, minLevel = 18, name = { ko = "검은심연의 음모", en = "Blackfathom Villainy" }, giver = { ko = "황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.", en = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff." } },
      { id = 6921, faction = "Horde", level = 27, minLevel = 21, name = { ko = "폐허 사이로", en = "Amongst the Ruins" }, giver = { ko = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.", en = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale." } },
      { id = 6922, rewards = { { id = 16886, name = { ko = "무법자 사브르", en = "Outlaw Sabre" } }, { id = 16887, name = { ko = "마녀의 손가락", en = "Witch's Finger" } }, { id = 270043, name = { ko = "꿈꾸는 자의 가슴보호대", en = "Dreamer's Chestguard" } } }, faction = "Horde", level = 30, minLevel = 21, name = { ko = "군주 아쿠아니스", en = "Baron Aquanis" }, giver = { ko = "잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다.", en = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale." } },
      { id = 1654, faction = "Alliance", level = 22, minLevel = 20, name = { ko = "정의의 시험", en = "The Test of Righteousness" }, giver = { ko = "이곳 나가(해일여사제·예언자)가 떨구는 부정한 코르석 등 네 가지를 아이언포지 조던 스틸웰에게(성기사).", en = "Kor Gem from the naga here (Tide Priestesses, Oracles) plus three other items to Jordan Stilwell in Ironforge (Paladin)." } },
      { id = 1740, level = 25, minLevel = 20, name = { ko = "소랜루크 수정구", en = "The Orb of Soran'ruk" }, giver = { ko = "황혼의 수행사제의 소랜루크 조각 3개와 큰 조각 1개(그림자송곳니 성채)를 불모의 땅 도안 카르한에게(흑마법사).", en = "3 Soran'ruk Fragments (Twilight Acolytes) and 1 Large Soran'ruk Fragment (Shadowfang Keep) to Doan Karhan in the Barrens (Warlock)." } },
    },
