  {
    key = "stocks", slug = "stockade", levels = "24-32",
    name = { ko = "스톰윈드 지하감옥", en = "The Stockade", de = "Verlies von Stormwind", fr = "Prison de Stormwind", es = "Mazmorras de Ventormenta", ru = "Тюрьма Штормграда", zhCN = "暴风城监狱", zhTW = "暴風城監獄" },
    instanceIDs = { 34 }, nameMatch = { "지하감옥", "Stockade", "Verlies von Stormwind", "Prison de Stormwind", "Mazmorras de Ventormenta", "Тюрьма Штормграда", "暴风城监狱", "暴風城監獄" },
    entrance = { map = 1453, x = 50.4, y = 66.2, zone = { ko = "스톰윈드 운하 지구", en = "Canal district of Stormwind City" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 1696 }, model = 517, name = { ko = "흉악범 타고르", en = "Targorr the Dread" }, quest = true, loot = { 273804, 273805, 273806 }, quests = { 386 }, tip = { ko = "감방 몇 곳 중 한 곳에 나타납니다(옅은 원이 후보). 쌍수 난타, 체력이 낮으면 분노.", en = "Spawns in one of several cells (faint circles). Thrash, enrages low." } },
      { id = "s2", n = "2", kind = "rare", optional = true, npc = { 1720 }, model = 2142, name = { ko = "브루갈 아이언너클", en = "Bruegal Ironknuckle" }, loot = { 3228, 2941, 2942 }, tip = { ko = "감방 한 곳에 나오는 희귀 몹. 지나가도 됩니다.", en = "Rare in one of the cells. Skippable." } },
      { id = "s3", n = "3", kind = "boss", npc = { 1666 }, model = 825, name = { ko = "캄 딥퓨리", en = "Kam Deepfury" }, quest = true, loot = { 273808, 2280, 273807 }, quests = { 378 }, tip = { ko = "방어 태세에서 방패 밀쳐내기.", en = "Defensive Stance, Shield Slam." } },
      { id = "s4", n = "4", kind = "boss", npc = { 1717 }, model = 3250, name = { ko = "햄혹", en = "Hamhock" }, loot = { 273809, 273810, 273811 }, tip = { ko = "연쇄 번개와 피의 욕망. 흩어져 서세요.", en = "Chain Lightning and Bloodlust; spread out." } },
      { id = "s5", n = "5", kind = "boss", npc = { 1716 }, model = 1621, name = { ko = "바질 스레드", en = "Bazil Thredd" }, quest = true, loot = { 273825, 273829, 273824, 273827 }, quests = { 391 }, tip = { ko = "연막탄으로 기절시키고 전투의 외침.", en = "Smoke Bomb stun and Battle Shout." } },
      { id = "s6", n = "6", kind = "boss", npc = { 1663 }, model = 2149, name = { ko = "덱스트렌 워드", en = "Dextren Ward" }, quest = true, loot = { 273819, 273820, 273817 }, quests = { 377 }, tip = { ko = "위협의 외침으로 공포. 공포 걸린 사람이 옆 무리를 끌 수 있으니 주변 감방을 먼저 비우세요.", en = "Intimidating Shout fears; feared players can pull cells, so clear around first." } },
    },
    quests = {
      { id = 386, faction = "Alliance", level = 25, minLevel = 22, name = { ko = "사필귀정", en = "What Comes Around..." }, giver = { ko = "흉악범 타고르를 처치한 후 그 증거로 그의 머리카락을 레이크샤이어에 있는 경비병 베르턴에게 가져가야 합니다.", en = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire." } },
      { id = 377, faction = "Alliance", level = 26, minLevel = 22, name = { ko = "죄와 벌", en = "Crime and Punishment" }, giver = { ko = "다크샤이어의 원로 밀스타이프가 덱스트렌 워드를 처치한 후 그의 장갑을 가져다 달라고 부탁했습니다.", en = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward." } },
      { id = 387, faction = "Alliance", level = 26, minLevel = 22, name = { ko = "폭동 진압", en = "Quell the Uprising" }, giver = { ko = "스톰윈드에 있는 교도소장 델워터가 지하감옥에서 데피아즈단 복역수 10명, 데피아즈단 무기징역수 8명, 데피아즈단 반역자 8명을 처치해 달라고 부탁했습니다.", en = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade." } },
      { id = 388, faction = "Alliance", level = 26, minLevel = 22, name = { ko = "피의 색", en = "The Color of Blood" }, giver = { ko = "스톰윈드에 있는 니코바 라스콜이 붉은 양모 복면을 10개를 모아 달라고 부탁했습니다.", en = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas." } },
      { id = 378, faction = "Alliance", level = 27, minLevel = 22, name = { ko = "격노", en = "The Fury Runs Deep" }, giver = { ko = "딥퓨리를 처치하고 그 증거로 그의 머리카락을 던 모드르에 있는 모틀리 가마슨에게 가져가야 합니다.", en = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr." } },
      { id = 391, faction = "Alliance", level = 29, minLevel = 16, name = { ko = "감옥 폭동", en = "The Stockade Riots" }, giver = { ko = "바질 스레드를 처치하고 그 증거로 그의 머리카락을 감옥에 있는 교도소장 델워터에게 가져가야 합니다.", en = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade." } },
    },
    trash = { 1076 },
    trashGroups = {
      { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 1076 }, from = { [1076] = { { n = { ko = "데피아즈단 반역자", en = "Defias Insurgent" }, r = 1 } } } },
    },
    notes = { { ko = "죄수가 감방마다 뭉쳐 있습니다. 문 앞에서 끌어내 복도에서 잡으세요.", en = "Prisoners clump in cells; pull them into the corridor." }, { ko = "얼라이언스는 스톰윈드 안이라 오가기 쉽습니다.", en = "Easy access for the Alliance inside Stormwind." } },
  },
  {
    key = "excav", slug = "excavation-site", levels = "26-33",
    name = { ko = "발굴 현장: 저습지", en = "Excavation Site: Wetlands", de = "Ausgrabungsstätte: Sumpfland", fr = "Excavations : les Paluns", es = "Excavación: Los Humedales", ru = "Раскопки: Болотина", zhCN = "挖掘场：湿地", zhTW = "挖掘場：濕地" },
    instanceIDs = { 2998 }, nameMatch = { "발굴 현장", "Excavation Site", "Ausgrabungsstätte: Sumpfland", "Excavations : les Paluns", "Excavación: Los Humedales", "Раскопки: Болотина", "挖掘场：湿地", "挖掘場：濕地" },
    entrance = { map = 1437, x = 47.8, y = 56.3, zone = { ko = "저습지 웰가르의 발굴현장 남동쪽 언덕 위의 포털", en = "Portal on the hill southeast of Whelgar's Excavation Site, Wetlands" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 260322 }, name = { ko = "소금가시", en = "Saltspine" }, aliases = { "Salzrücken", "Seléchine", "Espinasal", "Солеспин", "盐脊", "鹽脊" }, loot = { 273022, 273023, 273024 }, tip = { ko = "잃어버린 늪을 도는 악어입니다. 주변을 비운 마른 땅으로 끌어와 잡으세요. 먼지 폭풍이 주위를 치고 명중률을 떨어뜨리니 원거리·치유사는 떨어져 서세요.", en = "Crocolisk patrolling the Lost Marsh; pull it to a cleared dry spot. Dust Storm hits everyone close and lowers hit chance, so ranged and healers stay back." } },
      { id = "s2", n = "2", kind = "boss", npc = { 260325 }, name = { ko = "그늘이빨", en = "Shadetooth" }, aliases = { "Schemenzahn", "Dent-Sombre", "Sombradiente", "Тенезуб", "暗齿", "蔭牙" }, loot = { 273025, 273027, 273106, 273026 }, tip = { ko = "추적자의 숲 오솔길을 수풀 사냥꾼 둘과 함께 돕니다. 공포의 포효에 달아나다 숨은 랩터를 끌기 쉬우니 풀숲부터 비우세요. 이 숲 랩터들이 덤불 랩터 가죽을 떨굽니다.", en = "Patrols the Stalker's Thicket path with two Thicket Hunters. Terrifying Roar can send players into hidden raptors, so clear the grass first. Raptors here drop Thicket Raptor Hides." } },
      { id = "s3", n = "3", kind = "boss", optional = true, npc = { 260808 }, name = { ko = "고원 공포", en = "Highland Horror" }, aliases = { "Hochlandschrecken", "Horreur des hautes-terres", "Horror de las Tierras Altas", "Ужас нагорья", "高地恐魔", "高地之懼" }, loot = { 270180 }, quest = true, quests = { 95646 }, tip = { ko = "기름 수액괴물에 둘러싸여 있으니 우두머리만 끌어내세요. 야생의 회복력은 끊고, 휘감는 뿌리가 넓게 오래 묶습니다. 얼라이언스 '고원의 공포'의 끔찍한 뿌리핵을 떨굽니다.", en = "Surrounded by Oil Slimes: pull it out alone. Interrupt Wild Regeneration; Entangling Roots holds a wide area for a long time. Drops the Horrible Rootcore for the Alliance quest Horrors in the Highland." } },
      { id = "s4", n = "4", kind = "boss", npc = { 260326 }, name = { ko = "유물 수호자", en = "Relic Guardian" }, aliases = { "Reliktwächter", "Gardien des reliques", "Guardián de reliquias", "Страж реликвий", "遗迹守卫者", "聖物守護者" }, quest = true, loot = { 273028, 273029, 273030, 273097, 270866 }, quests = { 95664, 95810 }, tip = { ko = "수호자의 터에 잠들어 있다가 옆 기둥의 티탄 장치를 누르면 깨어납니다. 회전 강타가 정면을 치니 파티 반대쪽으로 돌리고, 날려버리기에 밀려 떨어지지 않게 가장자리는 피하세요. 티탄의 유물을 떨굽니다.", en = "Dormant at the Site of the Guardian; use the titan device by the pillar beside it to wake it. Arcing Smash hits the front, so face it away; keep off the edge because of Knock Away. Drops the Titan Relic." } },
    },
    quests = {
      { id = 98815, faction = "Alliance", level = 28, minLevel = 24, name = { ko = "고원 가죽", en = "Highland Hides" }, giver = { ko = "덤불 랩터 가죽 4장을 메네실 항구의 무두장이 제임스 할로란에게 가져가야 합니다.", en = "Return 4 Thicket Raptor Hides to James Halloran, the tanner, in Menethil Harbor." } },
      { id = 95646, faction = "Alliance", level = 31, minLevel = 24, name = { ko = "고원의 공포", en = "Horrors in the Highland" }, giver = { ko = "발굴 현장에서 고원 공포를 처치하고 그 뿌리핵을 저습지에 있는 신록의수호자 레시엘에게 가져가야 합니다.", en = "Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands." } },
      { id = 95647, faction = "Alliance", level = 31, minLevel = 24, name = { ko = "덤불 속 실종자", en = "Lost in the Thicket Things" }, giver = { ko = "발굴 현장에서 아르딘 그래스맨을 찾아야 합니다.", en = "Find Ardin Grassman in the Excavation Sites." } },
      { id = 95810, faction = "Alliance", level = 31, minLevel = 24, name = { ko = "잃어버린 유물 수송", en = "Lost Relic Carry" }, giver = { ko = "티탄의 유물을 저습지 발굴현장에 있는 발굴조사단장 웰가르에게 가져가야 합니다. 후속 퀘스트용 유물을 돌려받으므로 다시 구할 필요가 없습니다.", en = "Bring the Titan Relic to Prospector Whelgar in the Wetlands excavation site. The relic is returned for the follow-up quest; you do not need to collect another." } },
      { id = 95772, faction = "Alliance", level = 31, minLevel = 24, name = { ko = "송블레이드 수색", en = "Songblade Search" }, giver = { ko = "웰가르의 발굴현장에서 도린 송블레이드의 형제 데윈을 찾아야 합니다.", en = "Look for Dorin Songblade's brother, Daewyn, in Whelgar's Excavation Site." } },
      { id = 95697, faction = "Horde", level = 31, minLevel = 24, name = { ko = "달라지는 입맛", en = "Changing Tastes" }, giver = { ko = "저습지의 발굴 현장에 들어가 덤불 랩터 고기 4개를 가져와야 합니다.", en = "Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat." } },
      { id = 95664, faction = "Horde", level = 31, minLevel = 24, name = { ko = "장로의 지식", en = "Elder Knowledge" }, giver = { ko = "티탄의 유물을 썬더 블러프의 장로의 봉우리로 가져가 그에 대해 알려 줄 사람을 찾아야 합니다. 후속 퀘스트용 유물을 돌려받으므로 다시 구할 필요가 없습니다.", en = "Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it. The relic is returned for the follow-up quest; you do not need to collect another." } },
      { id = 95682, level = 31, minLevel = 24, name = { ko = "용아귀 열기", en = "Open the Maw" }, giver = { ko = "발굴 현장에서 용아귀 파괴공작원 2명과 용아귀 감시병 4명을 처치하고 용아귀 급보를 가져와야 합니다.", en = "Kill 2 Dragonmaw Saboteurs and 4 Dragonmaw Warders in the Excavation Site and bring back the Dragonmaw Dispatch." } },
    },
    trash = { 286982, 286983, 286984, 286985, 286986, 287068 },
    trashGroups = { { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 286982, 286983, 286984, 286985, 286986, 287068 } } },
    notes = { { ko = "만남의 돌은 저습지 53.4, 65.3입니다.", en = "Meeting stone: Wetlands 53.4, 65.3." }, { ko = "추적자의 숲에 정예 랩터가 많습니다.", en = "Many elite raptors in Stalker's Thicket." }, { ko = "티탄의 유물 전달 퀘스트를 완료하면 후속 퀘스트에 쓸 유물을 돌려받습니다. 다음 단계를 위해 유물 수호자를 다시 처치할 필요가 없습니다.", en = "The Titan Relic is returned after the delivery quest for use in its follow-up. You do not need to kill the Relic Guardian again for another relic." } },
  },
  {
    key = "dala", slug = "dalaran", levels = "28-35",
    name = { ko = "달라란", en = "City of Dalaran", de = "Dalaran", fr = "Cité de Dalaran", es = "Ciudad de Dalaran", ru = "Даларан", zhCN = "达拉然城", zhTW = "達拉然城" },
    instanceIDs = { 2959 }, nameMatch = { "달라란", "Dalaran", "Cité de Dalaran", "Ciudad de Dalaran", "Даларан", "达拉然城", "達拉然城" },
    entrance = { map = 1421, x = 69.6, y = 46.1, zone = { ko = "은빛소나무 숲 로다미어 호수 달라란 하수도 입구", en = "Dalaran sewer entrance by Lordamere Lake, Silverpine Forest" }, note = { ko = "하수도 문은 달라란 하수도 열쇠로 엽니다. 도시 안에서는 하수도의 선술집 옆 통로로 갈 수 있습니다.", en = "The outer sewer gate requires the Dalaran Sewer Key. From inside the city, use the passage beside the Underbelly tavern." } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 247126 }, name = { ko = "무덤 기사 아트렉시스", en = "Atrexis the Grave Knight" }, aliases = { "Atrexis der Grabritter", "Atrexis le Chevalier de la tombe", "Atrexis el Caballero de la Tumba", "Атрексий Могильный Рыцарь", "墓穴骑士阿特雷克斯", "『墓地騎士』亞崔希斯" }, quest = true, loot = { 273036, 273032, 273033 }, quests = { 96986 }, tip = { ko = "마법의 뒤안길 한가운데 의식진. 키린 토 강령술사 몇을 먼저 떼어 잡고 시작하세요. 일어나는 해골은 약하니 바로 정리하고, 무장 해제당한 탱커는 몇 초만 버티면 됩니다. 호드 '무덤 기사' 대상.", en = "Ritual circle in the middle of the Underbelly. Pull a few Kirin Tor Necromancers away first; the rising skeletons are weak, kill them at once, and the disarmed tank only has to hold a few seconds. Horde quest The Grave Knight." } },
      { id = "s7", n = "2", kind = "boss", npc = { 247032 }, optional = true, name = { ko = "외면받는 린", en = "Lyn the Ignored" }, aliases = { "Lyn der Ignorierte", "Lyn l’Ignoré", "Lyn el Ignorado", "Лин Забытый", "被无视的琳恩", "『忽視者』林恩" }, loot = { 273054, 273053, 273055 }, tip = { ko = "하수도 작은 원형 방의 의식진에 달라란의 고서를 쓰면 나오는 숨은 우두머리(고서 만드는 법은 준비 탭). 탱커에게 거는 가시의 저주는 바로 해제하고 해골은 나오는 대로 잡으세요.", en = "Hidden boss: use the Tome of Dalaran on the ritual circle in the sewers' small round room (how to make it: Prep tab). Decurse Curse of Thorns from the tank and kill the skeletons as they rise." } },
      { id = "s2", n = "3", kind = "boss", npc = { 245999 }, name = { ko = "비전 변형물", en = "Arcane Anomaly" }, aliases = { "Arkananomalie", "Anomalie arcanique", "Anomalía Arcana", "Волшебная аномалия", "奥术畸体", "秘法異象" }, loot = { 273031, 273034, 273035 }, tip = { ko = "둥근 테라스의 거품에서 끌려 나오며 싸움이 시작됩니다. 초점 폭발 시전(3초)이 보이면 정면을 벗어나 우두머리 뒤로 가세요. 광선이 6초간 이어지고, 그 사이 탱커는 비전 화살을 맞습니다.", en = "The fight starts when it is pulled out of a bubble on the Round Terrace. When Focal Blast starts (3s cast), leave its front and get behind it; the beam lasts 6s. The tank takes Arcane Bolts in between." } },
      { id = "s3", n = "4", kind = "boss", npc = { 246003 }, name = { ko = "지옥의 고대정령", en = "Fel Ancient" }, aliases = { "Teufelsurtum", "Ancien gangrené", "Anciano vil", "Древень Скверны", "邪能古树", "魔化古樹" }, loot = { 273039, 273038, 273037 }, tip = { ko = "도시 한가운데 룬위버 광장, 퍼진 나무정령들 사이. 지옥 목재 덩굴이 한 명에게 뻗어 5미터 안을 치고 독성 증기를 남기니 바로 벗어나세요. 휘감기에 묶인 사람은 풀어 주세요.", en = "Runeweaver Square in the city centre, among Suffused Treants. Fel Timbers lashes one player, hits everyone within 5 yd and leaves toxic vapour: get out. Free players held by Entangle." } },
      { id = "s5", n = "5", kind = "boss", npc = { 246008 }, name = { ko = "마나 포식자", en = "Mana Devourer" }, aliases = { "Manaschlinger", "Dévoreur de mana", "Devorador de maná", "Пожиратель маны", "法力吞噬者" }, loot = { 273040, 273042, 273041 }, tip = { ko = "보랏빛 요새 쪽 물 위 다리·계단에서 싸웁니다. 주변 몹이 함께 덤비니 미리 다 잡으세요. 탱커에게 활력 흡수로 지속 비전 피해를 주고 쇠약으로 마나를 빼앗으니 치유사 마나를 아끼세요.", en = "Fought on the bridges and stairs over the water by the Violet Hold. Nearby mobs join in, so clear them first. Drain Vitality puts arcane damage over time on the tank and Debilitate drains mana: healers save mana." } },
      { id = "s6", n = "6", kind = "boss", npc = { 246016 }, name = { ko = "신비한 수수께끼", en = "Arcanic Enigma" }, aliases = { "Mana Elemental", "Arcanic Enigma", "마나 정령", "Manaelementar", "Élémentaire de mana", "Elemental de maná", "Элементаль маны", "法力元素" }, quest = true, loot = { 273045, 273044, 273043 }, quests = { 92489 }, tip = { ko = "곁의 쫄 둘이 마나 연소를 쓰니 끊으며 먼저 잡으세요. 마나변이체(8초 변이)는 마법이라 해제하고, 침묵이 닿지 않게 치유사는 멀리 섭니다. 신비한 마나의 정령은 광역으로. 얼라이언스 '압도적인 힘' 대상.", en = "Its two adds cast Mana Burn: interrupt and kill them first. Dispel Manamorph (8s polymorph, magic); healers stay out of its silence. AoE the Arcane Manalings. Alliance quest Power Overwhelming." } },
      { id = "s4", n = "7", kind = "boss", npc = { 246017 }, name = { ko = "불안정한 파수꾼", en = "Unstable Sentinel" }, aliases = { "Instabile Schildwache", "Sentinelle instable", "Centinela inestable", "Нестабильный часовой", "不稳定的哨兵", "不穩定的哨兵" }, loot = { 273046, 273048, 273047, 273099 }, tip = { ko = "마법사 교역소. 가는 길의 성난 고서부터 잡으세요. 기능 장애 시전(2초)이 보이면 근접은 빠지고, 원거리는 늘 25미터 밖에 서세요. 6초 동안 2초마다 터집니다.", en = "Magus Commerce Exchange; kill the Angry Tomes on the way first. When Malfunction starts (2s cast) melee step out; ranged always stay beyond 25 yd. It pulses every 2s for 6s." } },
      { id = "s9", n = "8", kind = "boss", npc = { 246020 }, name = { ko = "대마법사의 망령", en = "Shade of the Archmage" }, aliases = { "Schemen des Erzmagiers", "Ombre de l’archimage", "Sombra del archimago", "Тень верховного мага", "大法师之影", "大法師之影" }, loot = { 273052, 273051, 273049, 273103 }, tip = { ko = "보랏빛 성채 앞 대마법사 모데라와 대화해 화려한 응접실로 갑니다. 튕기는 마나가 오가는 길목엔 비전 피해와 침묵이 있으니 비켜 서세요. 마나가 바닥나면 대규모 변이 뒤 환기. 방을 나가면 체력이 다 찹니다.", en = "Talk to Archmage Modera in front of the Violet Citadel to reach the Purple Parlor. Bounding Mana flies out and back, hitting and silencing anyone in its path: stand clear. Out of mana he casts Mass Polymorph, then Evocation. Leaving the room resets him." } },
    },
    quests = {
      { id = 92456, rewards = { { id = 279835, name = { ko = "덩굴치기의 망토", en = "Vine Pruner's Cloak" } }, { id = 279836, name = { ko = "가시막이 요대", en = "Thorn Protecting Girdle" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "녹빛 표본", en = "A Green Sample" }, giver = { ko = "달라란에서 지옥 마력이 주입된 꽃을 구해 스톰윈드에 있는 샤이라미르에게 가져가야 합니다.", en = "Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City." } },
      { id = 92458, rewards = { { id = 279839, name = { ko = "주문수호 견갑", en = "Spellguard Pauldrons" } }, { id = 279840, name = { ko = "소생의 발보호구", en = "Renewing Footpads" } }, { id = 279841, name = { ko = "달라란의 수호자", en = "Defender of Dalaran" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "분열의 심장", en = "Heart of Disruption" }, giver = { ko = "달라란 근처의 대마법사 모데라의 환영을 위해 달라란에서 비전 티끌을 구해야 합니다. 이 퀘스트를 받으면 달라란 하수도 열쇠를 줍니다.", en = "Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran. Taking it gives you the Dalaran Sewer Key." } },
      { id = 92489, rewards = { { id = 251962, name = { ko = "보랏빛 장식띠", en = "Violet Sash" } }, { id = 279849, name = { ko = "룬결속 장갑", en = "Runebound Gloves" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "압도적인 힘", en = "Power Overwhelming" }, giver = { ko = "스톰윈드에 있는 고위마술사 안드로매스를 위해 달라란에서 마나 정령을 처치해야 합니다.", en = "Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City." } },
      { id = 96984, rewards = { { id = 279842, name = { ko = "전투 어깨덮개", en = "Battle Spaulders" } }, { id = 279843, name = { ko = "마력 깃든 덧신", en = "Enchanted Sandals" } }, { id = 279844, name = { ko = "강타의 지팡이", en = "Striking Staff" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "분열의 심장", en = "Heart of Disruption" }, giver = { ko = "타렌 밀농장에 있는 마법학자 워딘 보이드글레어를 위해 달라란에서 비전 티끌을 구해야 합니다. 이 퀘스트를 받으면 달라란 하수도 열쇠를 줍니다.", en = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill. Taking it gives you the Dalaran Sewer Key." } },
      { id = 96987, rewards = { { id = 279845, name = { ko = "순금 고리", en = "Solid Gold Band" } }, { id = 279846, name = { ko = "절도범의 허리띠", en = "Larcenist's Belt" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "기회주의 학습법", en = "Opportunistic Education" }, giver = { ko = "하수도 입구 근처에 있는 렉시 코퍼클러치를 위해 달라란에서 달라란 건국사를 구해야 합니다.", en = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance." } },
      { id = 96986, rewards = { { id = 251963, name = { ko = "무덤걸이 장화", en = "Gravewalker Boots" } }, { id = 251965, name = { ko = "언데드 기사의 팔보호구", en = "Undead Knight's Bracers" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "무덤 기사", en = "The Grave Knight" }, giver = { ko = "타렌 밀농장에 있는 멜리사라를 위해 달라란에서 무덤 기사 아트렉시스를 쓰러뜨려야 합니다.", en = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill." } },
      { id = 96988, rewards = { { id = 279847, name = { ko = "불안정한 동력 핵", en = "Unstable Power Core" } }, { id = 279848, name = { ko = "피조물 망토", en = "Construct Cloak" } } }, faction = "Horde", level = 33, minLevel = 24, name = { ko = "힘의 원천", en = "Source of Power" }, giver = { ko = "언더시티에 있는 박사 마틴 펠벤을 위해 달라란에서 금이 간 파수꾼 핵 6개를 모아야 합니다.", en = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity." } },
      { id = 92457, rewards = { { id = 279837, name = { ko = "쓰러진 경비병의 펜던트", en = "Fallen Guard's Pendant" } }, { id = 279838, name = { ko = "비전 마력이 주입된 마법막대", en = "Arcane Infused Rod" } } }, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "비전에 굶주린 자들", en = "Starving Arcane" }, giver = { ko = "달라란 안에서 추적하는 잔재·포화된 잔재·마나 메아리를 8마리씩 잡고 대마법사 모데라에게.", en = "Kill 8 each of Seeking Remnants, Saturated Remnants and Mana Echoes inside Dalaran for Archmage Modera." } },
      { id = 92459, faction = "Alliance", level = 33, minLevel = 24, name = { ko = "키린 토의 친구", en = "Friend of the Kirin Tor" }, giver = { ko = "입장 연계 마지막. 대마법사의 망령이 떨군 비전 티끌을 달라란의 대마법사 셀린드라에게.", en = "Attunement finale: the Arcane Mote from the Shade of the Archmage to Archmage Celindra in Dalaran." } },
      { id = 97287, faction = "Horde", level = 33, minLevel = 24, name = { ko = "영리한 협상", en = "Shrewd Negotiations" }, giver = { ko = "입장 연계 마지막(호드). 대마법사의 망령이 떨군 비전 티끌을 달라란 근처 대마법사 모데라의 환영에게.", en = "Horde attunement finale: the Arcane Mote from the Shade of the Archmage to the Image of Archmage Modera near Dalaran." } },
    },
    trash = { 273043, 286987, 286988, 286989, 286992 },
    trashGroups = {
      { name = { ko = "일반 몹", en = "Trash mobs" }, trash = true, loot = { 273043, 286987, 286988, 286989, 286992 } },
    },
    notes = { { ko = "호드 주의: 10월 15일 패치부터 하수도 열쇠를 얻어도 야외 달라란 도시에서는 공격받습니다. 도시 자유 출입 권한은 없어졌지만 하수도를 통한 달라란 던전 입장은 가능합니다.", en = "Horde warning: since the October 15 update, the sewer key no longer grants safe access to outdoor Dalaran; city NPCs attack Horde on sight. Dungeon access through the sewers is unchanged." }, { ko = "권장 28~33레벨이고 던전 퀘스트는 24레벨부터 받습니다.", en = "Levels 28-33; dungeon quests from level 24." }, { ko = "입구는 하수도를 지나 긴 관 끝의 차원문. 하수도 문은 입장 퀘스트로 받는 달라란 하수도 열쇠로 열고, 입장 퀘스트를 마친 사람이 파티에 한 명 있으면 모두 들어갑니다.", en = "Entrance: the portal at the end of a long pipe through the sewers. The sewer door needs the Dalaran Sewer Key from the attunement; one attuned member lets the whole group in." }, { ko = "얼라이언스 입장: 힐스브래드 사절 자크 '불길한 요청'(30레벨~) → 은빛소나무 숲 동쪽 끝 대마법사 모데라의 환영 '분열의 심장'(열쇠) → 보랏빛 성채 대마법사 셀린드라 '키린 토의 친구'.", en = "Alliance attunement: An Alarming Request (Emissary Jacques, Hillsbrad, from 30) → Heart of Disruption (Image of Archmage Modera, east Silverpine; gives the key) → Friend of the Kirin Tor (Archmage Celindra)." }, { ko = "호드 입장: 타렌 밀농장 마법학자 워딘 보이드글레어의 다른 퀘스트를 끝낸 뒤 '거리에 흐르는 피'(30레벨~) → '분열의 심장' → '영리한 협상'(대마법사 모데라의 환영에게 보고).", en = "Horde attunement: finish Magus Wordeen Voidglare's other quests in Tarren Mill, then Blood in the Streets (from 30) → Heart of Disruption → Shrewd Negotiations (report to the Image of Archmage Modera)." }, { ko = "희귀 외면받는 린: 그림자송곳니 성채 아루갈 뒤의 검은 고서를 은빛소나무 숲 앰버밀(63.4, 64.3)의 수정에 쓰면 달라란의 고서가 됩니다.", en = "Rare Lyn the Ignored: use the Black Tome (behind Arugal, Shadowfang Keep) on the crystal at Ambermill, Silverpine (63.4, 64.3) to make the Tome of Dalaran." }, { ko = "하수도에서 시작해 도시로 올라갑니다. 하수도와 도시를 별도 미니맵으로 표시하며, 연결 표식을 누르면 다른 구역으로 전환합니다. 보스 표식은 공략 자료를 참고한 위치입니다.", en = "The run starts in the sewers and climbs to the city. The floors have separate native minimaps and reciprocal clickable guide links. Boss markers are registered guide reference positions." } },
  },
  {
    key = "gnomer", slug = "gnomeregan", levels = "29-38",
    name = { ko = "놈리건", en = "Gnomeregan", de = "Gnomeregan", fr = "Gnomeregan", es = "Gnomeregan", ru = "Гномреган", zhCN = "诺莫瑞根", zhTW = "諾姆瑞根" },
    instanceIDs = { 90 }, nameMatch = { "놈리건", "Gnomeregan", "Гномреган", "诺莫瑞根", "諾姆瑞根" },
    entrance = { map = 1426, x = 17.7, y = 39.2, zone = { ko = "던 모로 서쪽 놈리건 정문", en = "The front gate of Gnomeregan in western Dun Morogh" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 7361 }, model = 6533, name = { ko = "그루비스", en = "Grubbis" }, loot = { 9445, 274042, 274043 }, tip = { ko = "폭발물전문가 에미에게 말을 걸면 에미가 입구를 폭파하는 동안 트로그가 몰려오고 끝에 그루비스가 나옵니다. 에미를 지키세요.", en = "Talk to Blastmaster Emi: troggs rush in while she seals the tunnels, then Grubbis comes. Keep Emi alive." } },
      { id = "s2", n = "2", kind = "boss", npc = { 7079 }, model = 5497, name = { ko = "방사성 폐기물", en = "Viscous Fallout" }, quest = true, loot = { 9454, 9453, 9452 }, quests = { 2962 }, tip = { ko = "방사능 구역의 우두머리. 근처 방사능 몹에게서 얼라이언스 '유일한 치료법'의 폐기물을 얻습니다.", en = "Boss of the irradiated zone. Mobs here give the fallout for the Alliance quest The Only Cure is More Green Glow." } },
      { id = "s3", n = "3", kind = "npc", name = { ko = "케르노비", en = "Kernobee" }, quest = true, quests = { 2904 }, tip = { ko = "케르노비를 찾아 태엽장치 통로 출구까지 호위하세요('곤경에 빠진 케르노비'). 서 있는 자리는 여러 곳 중 하나.", en = "Find Kernobee and escort him to the Clockwerk Run exit (A Fine Mess). He stands at one of several spots." } },
      { id = "s4", n = "4", kind = "object", optional = true, name = { ko = "삐까뻔쩍세척기 5200", en = "The Sparklematic 5200" }, quest = true, quests = { 2930, 2945, 2951 }, tip = { ko = "정화 지역의 세척기. 꼬질꼬질한 반지를 넣어 닦습니다. 근처에 행렬 천공기록기 3005-B.", en = "Sparklematic in the Clean Zone: clean the Grime-Encrusted Ring here. Matrix Punchograph 3005-B is nearby." } },
      { id = "s5", n = "5", kind = "boss", npc = { 6235 }, model = 6915, name = { ko = "기계화 문지기 6000", en = "Electrocutioner 6000" }, quest = true, loot = { 9447, 9446, 9448, 6893 }, quests = { 2930 }, tip = { ko = "전격·연쇄 벼락·100만 볼트. 흩어져 서세요. 작업장 열쇠를 떨구고, 방에 행렬 천공기록기 3005-C.", en = "Shock, Chain Bolt, Megavolt. Spread out. Drops the Workshop Key; Matrix Punchograph 3005-C is in his room." } },
      { id = "s6", n = "6", kind = "boss", npc = { 6229 }, model = 6774, name = { ko = "고철 압축기 9-60", en = "Crowd Pummeler 9-60" }, quest = true, loot = { 9449, 9450, 274049, 274068 }, quests = { 2930 }, tip = { ko = "회전 강타·밟아 뭉개기·고철 압축으로 주변을 칩니다. 근접은 옆·뒤, 원거리는 멀리. 출격실에 행렬 천공기록기 3005-D.", en = "Arcing Smash, Trample, Crowd Pummel hit all around. Melee at sides/back, ranged far. Matrix Punchograph 3005-D is in the Launch Bay." } },
      { id = "s7", n = "7", kind = "rare", optional = true, npc = { 6228 }, model = 6669, name = { ko = "검은무쇠 사절", en = "Dark Iron Ambassador" }, loot = { 9455, 9456, 9457 }, tip = { ko = "희귀 몹. 화염구, 화염 보호막·냉기 갑옷, 불타는 하수인 소환. 지나가도 됩니다.", en = "Rare: Fireball, Fire Shield, Frost Armor, summons a servant. Skippable." } },
      { id = "s8", n = "8", kind = "npc", optional = true, name = { ko = "검은무쇠단 첩보원", en = "Dark Iron Agent" }, quest = true, quests = { 2945 }, tip = { ko = "첩보원이 떨구는 꼬질꼬질한 반지로 같은 이름의 퀘스트가 시작됩니다. 여러 곳에 나옵니다.", en = "Agents drop the Grime-Encrusted Ring that starts its quest. Found in many places." } },
      { id = "s9", n = "9", kind = "boss", npc = { 7800 }, model = 6980, name = { ko = "기계박사 텔마플러그", en = "Mekgineer Thermaplugg" }, quest = true, loot = { 9461, 9458, 4415, 4413, 4411, 7742, 9492, 9459, 6672, 7192, 7560, 7561 }, quests = { 2841, 2929 }, tip = { ko = "날려버리기로 탱커를 밀칩니다. 방 둘레 놈 얼굴 장치에서 폭탄 로봇이 나오니 장치를 누르거나 로봇을 먼저 처리.", en = "Knock Away on the tank. Bombs walk out of the gnome-face machines; press them or kill bombs first." } },
      { id = "s10", n = "10", kind = "object", optional = true, name = { ko = "텔마플러그의 금고", en = "Thermaplugg's Safe" }, quest = true, quests = { 2841 }, tip = { ko = "호드 '기술 전쟁'의 설계도가 든 금고. 비밀번호는 텔마플러그가 떨굽니다.", en = "Safe with the blueprints for the Horde quest Rig Wars; Thermaplugg drops the code." } },
    },
    quests = {
      { id = 2962, faction = "Alliance", level = 30, minLevel = 20, name = { ko = "유일한 치료법", en = "The Only Cure is More Green Glow" }, giver = { ko = "놈리건으로 가서 고농축 방사성 폐기물을 가져와야 합니다. 이 폐기물은 불안정하여 성분이 금방 변할 수 있으니 주의하십시오. 임무를 완수한 후 빈 대형 가연채집병을 오지에게 돌려줘야 합니다.", en = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly. Ozzie will also require your Heavy Leaden Collection Phial when the task is complete." } },
      { id = 2930, faction = "Alliance", level = 30, minLevel = 25, name = { ko = "자료 회수", en = "Data Rescue" }, giver = { ko = "아이언포지에 있는 수석수리공 캐스트파이프에게 오색 천공 카드를 가져가야 합니다.", en = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge." } },
      { id = 2924, faction = "Alliance", level = 30, minLevel = 24, name = { ko = "필수 인공장치", en = "Essential Artificials" }, giver = { ko = "아이언포지에 있는 클락몰트 스패너스판에게 필수 인공장치 12개를 가져가야 합니다.", en = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge." } },
      { id = 2928, faction = "Alliance", level = 30, minLevel = 20, name = { ko = "회전천공식 발굴기", en = "Gyrodrillmatic Excavationators" }, giver = { ko = "스톰윈드에 있는 쇼니에게 기계장치 부속품 24개를 가져가야 합니다.", en = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind." } },
      { id = 2929, faction = "Alliance", level = 35, minLevel = 25, name = { ko = "대배반", en = "The Grand Betrayal" }, giver = { ko = "놈리건으로 가서 기계박사 텔마플러그를 처치해야 합니다. 임무가 끝나면 땜장이왕 멕카토크에게 돌아와야 합니다.", en = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete." } },
      { id = 95041, minLevel = 7, faction = "Alliance", name = { ko = "자료 수집광", en = "Data Hoarders" }, giver = { ko = "놈리건 전역의 놈리건 보관 자료 카드 7장을 수집한 후, 아이언포지에 있는 젬마 퀵스위치에게 전달해야 합니다.", en = "Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge." } },
      { id = 2841, faction = "Horde", level = 35, minLevel = 25, name = { ko = "기술 전쟁", en = "Rig Wars" }, giver = { ko = "놈리건에서 장치 설계도와 텔마플러그의 금고 암호를 찾아서 오그리마에 있는 노그에게 가져다주어야 합니다.", en = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar." } },
      { id = 2904, level = 30, minLevel = 20, name = { ko = "곤경에 빠진 케르노비", en = "A Fine Mess" }, giver = { ko = "태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.", en = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay." } },
      { id = 2951, level = 30, minLevel = 25, name = { ko = "삐까뻔쩍세척기 5200!", en = "The Sparklematic 5200!" }, giver = { ko = "삐까뻔쩍세척기 5200에 꼬질꼬질한 물건을 넣으십시오. 3실버를 투입하면 작동할 것입니다.", en = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine." } },
      { id = 2945, level = 34, minLevel = 28, name = { ko = "꼬질꼬질한 반지", en = "Grime-Encrusted Ring" }, giver = { ko = "꼬질꼬질한 반지에서 찌꺼기를 제거할 방법을 찾아야 합니다.", en = "Figure out a way to remove the grime from the Grime-Encrusted Ring." } },
