    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 3974 }, model = 2040, name = { ko = "사냥개조련사 록시", en = "Houndmaster Loksey" }, quest = true, loot = { 7710, 7756, 3456, 274292 }, quests = { 1048, 1053, 1113 }, tip = { ko = "사냥꾼의 회랑에서 사냥개 여럿과 함께 덤빕니다. 피의 욕망으로 공격이 빨라지니 탱커 힐을 넉넉히 하고, 개들은 광역으로 한꺼번에 잡거나 먼저 정리하세요.", en = "In the Huntsman's Cloister with a pack of hounds. Bloodlust speeds up his swings, so keep the tank topped; AoE the dogs together or kill them first." } },
      { id = "s2", n = "2", kind = "object", optional = true, name = { ko = "티탄 신화", en = "Mythology of the Titans" }, quest = true, quests = { 1050 }, tip = { ko = "얼라이언스 '티탄 신화'의 책입니다. 집어서 아이언포지의 사서 메이 페일더스트에게 가져가세요.", en = "The book for the Alliance quest Mythology of the Titans; bring it to Librarian Mae Paledust in Ironforge." } },
