      { id = "s4", n = "4", kind = "object", optional = true, name = { ko = "타락의 개요", en = "Compendium of the Fallen" }, quest = true, quests = { 1049 }, tip = { ko = "호드 '타락의 개요'의 책입니다. 썬더 블러프의 현자 트루스시커에게 가져가세요(오크·타우렌·트롤).", en = "Book for the Horde quest Compendium of the Fallen; bring it to Sage Truthseeker in Thunder Bluff (Orc, Tauren, Troll)." } },
      { id = "s5", n = "5", kind = "object", optional = true, name = { ko = "마력의 의식", en = "Rituals of Power" }, quest = true, quests = { 1951 }, tip = { ko = "마법사 퀘스트 '마력의 의식'의 책입니다. 먼지진흙 습지대의 타베사에게 가져가세요.", en = "Book for the mage quest Rituals of Power; bring it to Tabetha in Dustwallow Marsh." } },
      { id = "s6", n = "6", kind = "boss", npc = { 6487 }, model = 5266, name = { ko = "신비술사 도안", en = "Arcanist Doan" }, loot = { 7714, 7713, 7711, 7712, 274293, 274294 }, tip = { ko = "곁에 붙으면 침묵에 걸리니 시전자는 떨어져 서세요. 절반쯤에 신비한 거품을 두르면 변이와 폭발이 이어지니 바로 멀리 달아납니다. 뒤쪽 도안의 금고에 붉은십자군 열쇠가 있습니다.", en = "His Silence hits everyone near him, so casters keep their distance. When he raises Arcane Bubble around half health, run: Polymorph and Detonation follow. The Scarlet Key is in Doan's Strongbox behind him." } },
    },
    quests = {
      { id = 96800, faction = "Alliance", level = 38, minLevel = 30, name = { ko = "반납 기한 초과", en = "Past Due" }, giver = { ko = "붉은십자군 수도원에서 잃어버린 룬술사의 마법을 회수.", en = "Retrieve The Lost Magic of the Runemasters from the Scarlet Monastery." } },
      { id = 1050, faction = "Alliance", level = 38, minLevel = 28, name = { ko = "티탄 신화", en = "Mythology of the Titans" }, giver = { ko = "수도원에서 티탄 신화라는 책을 찾아 아이언포지에 있는 사서 메이 페일더스트에게 가져가야 합니다.", en = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge." } },
      { id = 1053, faction = "Alliance", level = 40, minLevel = 34, name = { ko = "빛의 이름으로!", en = "In the Name of the Light" }, giver = { ko = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 사우스쇼어에 있는 경건한 신자 랄레이에게 돌아가 보고하십시오.", en = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore." } },
      { id = 1113, faction = "Horde", level = 33, minLevel = 30, name = { ko = "열정의 증거", en = "Hearts of Zeal" }, giver = { ko = "언더시티에 있는 수석 연금술사 파라넬에게 열정의 증거 20개를 가져가야 합니다.", en = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal." } },
      { id = 1160, faction = "Horde", level = 36, minLevel = 26, name = { ko = "지혜의 시험", en = "Test of Lore" }, giver = { ko = "언데드 위협의 기원을 찾아 언더시티에 있는 파쿠알 핀탈라스에게 가져가야 합니다.", en = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity." } },
      { id = 1049, faction = "Horde", level = 38, minLevel = 28, name = { ko = "타락의 개요", en = "Compendium of the Fallen" }, giver = { ko = "수도원에서 타락의 개요를 찾아 썬더 블러프의 현자 트루스시커에게(오크·타우렌·트롤).", en = "Bring the Compendium of the Fallen from the Monastery to Sage Truthseeker in Thunder Bluff (Orc, Tauren, Troll)." } },
      { id = 1048, faction = "Horde", level = 42, minLevel = 33, name = { ko = "붉은십자군 수도원으로", en = "Into The Scarlet Monastery" }, giver = { ko = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 언더시티에 있는 바리마트라스에게 돌아가 보고해야 합니다.", en = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity." } },
      { id = 1951, level = 40, minLevel = 30, name = { ko = "마력의 의식", en = "Rituals of Power" }, giver = { ko = "마력의 의식 책을 먼지진흙 습지대의 타베사에게(마법사).", en = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh (Mage)." } },
      { id = 78676, level = 35, minLevel = 25, name = { ko = "보스카의 눈", en = "The Eye of Bhossca" }, giver = { ko = "수도원에서 보스카의 눈을 찾아 장작나무 마을 근처 C의 은닉처에 혼자 가져가기(도적).", en = "Find the Eye of Bhossca in the Monastery and bring it alone to C's dead drop near Pyrewood Village (rogue)." } },
