  {
    key = "drowned", slug = "the-drowned-city", levels = "35-42",
    name = { ko = "가라앉은 도시", en = "The Drowned City", de = "Die Versunkene Stadt", fr = "La cité Submergée", es = "La Ciudad Sumergida", ru = "Затонувший город", zhCN = "沉没之城", zhTW = "沉沒之城" },
    instanceIDs = { 2970 }, nameMatch = { "가라앉은 도시", "The Drowned City", "Затонувший город", "沉没之城", "沉沒之城" },
    entrance = { map = 1434, x = 21.4, y = 27.9, zone = { ko = "가시덤불 골짜기 서북쪽 앞바다 물속 동굴(큰 석판 옆)", en = "Underwater off northwest Stranglethorn: the cave with a large tablet beside it" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 258905 }, name = { ko = "줄알라이", en = "Zul'Alai" }, aliases = { "Zul’Alai", "Зул'алай", "祖拉莱", "祖爾阿萊" }, loot = { 274599, 274598, 274600 }, tip = { ko = "가까이 있으면 3초 기절이라 원거리는 떨어지세요. 둔화 공격은 해제하고, 체력 30%부터는 몰아서 잡으세요.", en = "Monstrous Slam stuns nearby players for 3s: ranged stay back. Dispel the slowing strike; burn him from 30%." } },
      { id = "s2", n = "2", kind = "rare", optional = true, npc = { 264172 }, name = { ko = "움브라", en = "Umbra" }, loot = { 286662, 286658 }, tip = { ko = "희귀 정예. 바르타카로 가는 계단 근처에서 출혈을 거는 멀록 다섯과 함께 나옵니다.", en = "Rare elite near the stairs to Var'Taka, with five murlocs that cause bleeding." } },
      { id = "s3", n = "3", kind = "boss", quest = true, npc = { 258924 }, name = { ko = "바르타카", en = "Var'Taka" }, aliases = { "Var’Taka", "Вар'така", "瓦尔塔卡", "伐塔卡" }, loot = { 274602, 274601, 274613 }, quests = { 95776 }, tip = { ko = "치유하는 여사제 둘은 차단하거나 묶으세요. 정면 베기가 있어 탱커만 앞에, 작살로 끌려가면 정면에서 비키세요.", en = "Interrupt or CC the two healing priestesses. Cleave: only the tank in front; if harpooned, step out of it." } },
      { id = "s4", n = "4", kind = "boss", quest = true, npc = { 260042 }, name = { ko = "대장 드레드라이즈", en = "Captain Dreadrise" }, aliases = { "Capitaine Lèveffroi", "Capitán Alzapavor", "Капитан Морожад", "德雷德莱斯船长", "懼湧船長" }, loot = { 274604, 274605, 274603 }, quests = { 95791 }, tip = { ko = "바닷물 절이기로 무작위 한 명을 심연의 거품에 가둬 익사시킵니다. 거품부터 깨고, 연발 물화살은 차단하세요.", en = "Embrine traps a random player in an Abyssal Bubble to drown: break it first. Interrupt Waterbolt Volley." } },
      { id = "s5", n = "5", kind = "rare", optional = true, npc = { 260468 }, name = { ko = "\"화염술사\" 브랙스턴", en = "\"Pyromancer\" Braxton" }, loot = { 286650, 286651 }, tip = { ko = "희귀 정예. 해적 구역에 나올 때가 있습니다.", en = "Rare elite; sometimes in the pirate section." } },
      { id = "s6", n = "6", kind = "boss", quest = true, npc = { 260202 }, name = { ko = "죽지 않는 골수 구체", en = "Deathless Marrow" }, aliases = { "죽지 않는 수호자", "Deathless Guardians", "Unsterbliche Wächter", "Gardiens impérissables", "Guardianes inextinguibles", "Неумирающие стражи", "不死守护者", "不滅的守護者" }, loot = { 274606, 274614, 274607 }, quests = { 97130, 96774 }, tip = { ko = "서쪽 제단에서 나옵니다. 나가가 셋씩 몰려오고 하나 잡을 때마다 우두머리가 받는 피해가 20% 늘어납니다. 기절을 거는 죽지 않는 수호자부터.", en = "Rises at the western altar with waves of three naga; each add killed makes it take 20% more damage. Kill the stunning Deathless Guardians first." } },
      { id = "s7", n = "7", kind = "rare", optional = true, npc = { 264177 }, name = { ko = "길", en = "Gill" }, loot = { 286646, 286649 }, tip = { ko = "희귀 정예. 태고의 정령에게 가는 길 근처. 다이너마이트가 광역이니 흩어지세요.", en = "Rare elite near the path to the Primeval Elemental. Throw Dynamite is AoE: spread out." } },
      { id = "s8", n = "8", kind = "boss", npc = { 263886, 273738 }, name = { ko = "태고의 정령", en = "Primeval Elemental" }, aliases = { "Urtümlicher Elementar", "Élémentaire primitif", "Elemental primigenio", "Первородный элементаль", "原始元素", "原初元素" }, loot = { 274612, 271718, 274611, 274615 }, tip = { ko = "심층 기록 보관소에서 물속으로 들어가는 아탈바이잘의 둥근 방. 방에서 죽지 않는 공물(트롤)을 다 잡으면 나옵니다. 광역 둔화가 있고, 탱커에게 쏘는 물화살은 차단하세요.", en = "In the round room of Ataal'Byzal, reached by diving from the Deep Archives: kill all Undying Offerings (trolls) to make it appear. AoE slow; interrupt the Waterbolt on the tank." } },
      { id = "s9", n = "9", kind = "boss", npc = { 260243, 267852 }, name = { ko = "독사 민로스", en = "Min'loth the Serpent" }, aliases = { "Min'loth die Schlange", "Min’loth le Serpent", "Min'loth la Serpiente", "Мин'лот-Змей", "毒蛇明洛斯", "聖蛇米洛斯" }, loot = { 274610, 274608, 274609 }, tip = { ko = "맨 서쪽. 트롤 모습일 때는 물벼락으로 탱커를, 체력이 낮아지면 폭우로 파티 전체를 칩니다. 쓰러지면 뱀으로 다시 일어나 연발 독액(해독)과 공포를 씁니다.", en = "Far west. As a troll he hits the tank with Drench and, when low, the whole party with Deluge. When he falls he rises as a serpent: Poison Bolt Volley (cure it) and Fear." } },
      { id = "s10", n = "10", kind = "boss", optional = true, npc = { 263742 }, name = { ko = "진아카", en = "Zin'aka" }, tip = { ko = "독사 민로스 너머 침수된 제단의 웅덩이에 있는 정예 야수. 게임의 우두머리 목록에는 없는 선택 처치 대상입니다.", en = "Elite beast in the pool of the Flooded Shrine, past Min'loth the Serpent. Not on the game's boss list: an optional kill." } },
    },
    quests = {
      { id = 97130, faction = "Alliance", level = 40, minLevel = 34, name = { ko = "고대 구루바시의 비밀", en = "Ancient Gurubashi Secrets" }, giver = { ko = "가라앉은 도시에서 고대 구루바시 우상을 회수해야 합니다.", en = "Recover an Ancient Gurubashi Idol from the Drowned City." } },
      { id = 95787, faction = "Alliance", level = 40, minLevel = 30, name = { ko = "다시 한번 물속으로", en = "Take Two With Water" }, giver = { ko = "가죽과 목탄을 사용해 가라앉은 도시에서 발견된 서판의 탁본을 만들어야 합니다.", en = "Use the hide and charcoal to create rubbings of the tablets found in the Drowned City." } },
