      { id = "s3", n = "3", kind = "boss", npc = { 3977 }, model = 2043, name = { ko = "종교재판관 화이트메인", en = "High Inquisitor Whitemane" }, quest = true, loot = { 7721, 7722, 7720 }, quests = { 1048, 1053, 1113 }, tip = { ko = "체력이 절반쯤 되면 깊은 수면으로 파티를 재우고 모그레인을 되살립니다. 그 전에 탱커 체력과 힐러 마나를 채워 두고, 둘이 함께 오면 치유하는 화이트메인부터 잡으세요.", en = "Around half health Deep Sleep puts the group to sleep and she raises Mograine. Top off the tank and healer mana before then, and once both fight, kill Whitemane, the healer, first." } },
