    instanceIDs = { 3039 }, nameMatch = { "크롤도크 보루", "Krol'dok Stronghold", "Крепость Крол'док", "克罗多克要塞", "克羅多克要塞" },
    entrance = { map = 2548, x = 37.5, y = 37.5, zone = { ko = "강물터 북쪽 언덕, 큰 요새 문 서쪽의 동굴", en = "Northern Riverglades hill: the cave west of the big fortress gates" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 258966 }, name = { ko = "노예파괴자 그록스", en = "Slavecrusher Grox" }, aliases = { "Sklavenbrecher Grox", "Brise-esclave Grox", "Machacaesclavos Grox", "Рабомучитель Грокс", "碎奴者格罗克斯", "碎奴者古羅斯" }, loot = { 274996, 274997, 274995 }, tip = { ko = "입구에서 오른쪽 아래 채석장을 순찰합니다. 그가 비운 사이 싸울 자리를 치우고 잡으세요. 복종의 강요로 붉은마루일족 포로를 불러내고, 가끔 탱커를 기절시킵니다.", en = "Patrols the quarry down and to the right of the entrance; clear a space while he is away, then pull. Force Compliance calls Redridge Prisoners, and he stuns the tank now and then." } },
      { id = "s2", n = "2", kind = "boss", quest = true, npc = { 258972 }, name = { ko = "황혼의 사령관 자르모크", en = "Twilight Commander Zarmok" }, aliases = { "Twilight-Kommandant Zarmok", "Commandant du Crépuscule Zarmok", "Comandante Crepuscular Zarmok", "Сумеречный командир Зармок", "暮光指挥官扎尔莫克", "暮光指揮官札莫克" }, loot = { 275000, 274998, 274999 }, quests = { 94975 }, tip = { ko = "큰 문 옆 진영을 순찰하니 무리에서 떨어졌을 때 끌어오세요. 분쇄의 소용돌이가 주위에 출혈을 남기니 근접은 잠시 빠지고, 무작위 대상에게 돌진도 합니다.", en = "Patrols the compound by the big gate; pull him once he is away from the packs. Rending Whirl leaves a bleed on everyone close, so melee step out; he also charges random players." } },
      { id = "s3", n = "3", kind = "boss", npc = { 259281 }, name = { ko = "전투조련사 아쉬카", en = "War Handler Ashka" }, aliases = { "조련사 아쉬카", "Handler Ashka", "Tierführerin Ashka", "Dresseuse Ashka", "Cuidadora Ashka", "Укротительница Ашка", "驯兽师阿什卡", "管理員艾絲卡" }, loot = { 275001, 275002, 275003 }, tip = { ko = "자르모크 다음 길가의 늑대 우리. '명령: 살상!'으로 으르렁송곳니와 공포울음을 무작위 대상에게 보내니 늑대 둘부터 잡으세요.", en = "Wolf pen by the road after Zarmok. Command: Kill! sends Snarlfang and Terrorhowl at random players: kill both wolves first." } },
      { id = "s4", n = "4", kind = "boss", quest = true, npc = { 258964 }, name = { ko = "나르구르크", en = "Nar'gurk" }, aliases = { "Nar’gurk", "Нар'гурк", "纳古克", "納古克" }, loot = { 275004, 275005, 275006, 267104 }, quests = { 94984, 94972 }, tip = { ko = "큰길 꼭대기 갈림길 왼쪽의 소환 원. 황혼의 흑마법사·잿빛가죽일족 저주술사부터 묶거나 잡으세요. 개종에 걸린 사람은 생명력이 절반이 되면 풀리니 묶어 두거나 때려서 푸세요.", en = "Summoning circle at the top of the main road, left at the fork. CC or kill the Twilight Warlocks and Shadowhide Curseweavers first. Convert charms a player until they drop to half health: hold them with CC or damage them free." } },
      { id = "s5", n = "5", kind = "boss", optional = true, npc = { 264773 }, name = { ko = "두목 투프", en = "Bossman Toof" }, loot = { 286430, 286429, 286428 }, tip = { ko = "두 다리 위에서 버티는 전투. 오우거가 둘씩 몰려온 뒤 크롤도크 주술사 둘과 함께 직접 싸웁니다.", en = "An endurance fight on two bridges: ogres come in pairs, then he fights with two Krol'dok Shamans." } },
      { id = "s6", n = "6", kind = "boss", quest = true, npc = { 258968 }, name = { ko = "대군주 머그", en = "Overlord Mugg" }, aliases = { "감독관 머그", "Overseer Mugg", "Aufseher Mugg", "Suzerain Mugg", "Sobrestante Mugg", "Надзиратель Магг", "监工莫格", "監督者馬戈" }, loot = { 275009, 275007, 275010, 275008, 267086, 271721 }, quests = { 94982, 94968 }, tip = { ko = "길 끝 집에서 크롤도크 백인대장 둘과 함께. 무작위 대상에게 뛰어들어 광역 피해를 주니 흩어지세요. 체력이 줄면 더 센 무기로 바꿉니다.", en = "In the house at the end of the path with two Krol'dok Centurions. Leaps on random players with AoE: spread out. Switches to stronger weapons as his health drops." } },
    },
