      { id = "s3", n = "3", kind = "boss", quest = true, npc = { 7228 }, model = 6089, name = { ko = "아이로나야", en = "Ironaya" }, loot = { 9409, 9407, 9408, 274484 }, quests = { 2240 }, tip = { ko = "봉인된 석실 안. 티솔의 자루(레벨로쉬)와 그니키브 메달(밸로그의 궤짝)로 만든 잃어버린 역사의 지팡이를 쐐기돌에 쓰면 깨어납니다. 회전 강타가 정면을 치고, 날려버리기·전투 발구르기도 씁니다.", en = "Inside the sealed Map Chamber. Make the Staff of Prehistoria from the Shaft of Tsol (Revelosh) and the Gni'kiv Medallion (Baelog's Chest) and use it on the Keystone to wake her. Arcing Smash hits her front; she also uses Knock Away and War Stomp." } },
