  {
    key = "zf", slug = "zul-farrak", levels = "44-54",
    name = { ko = "줄파락", en = "Zul'Farrak", de = "Zul'Farrak", fr = "Zul'Farrak", es = "Zul'Farrak", ru = "Зул'Фаррак", zhCN = "祖尔法拉克", zhTW = "祖爾法拉克" },
    instanceIDs = { 209 }, nameMatch = { "줄파락", "Zul'Farrak", "Зул'Фаррак", "祖尔法拉克", "祖爾法拉克" },
    entrance = { map = 1446, x = 39.0, y = 20.0, zone = { ko = "타나리스 북서쪽, 줄파락 성문", en = "Northwest Tanaris, at the gates of Zul'Farrak" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 8127 }, name = { ko = "안투술", en = "Antu'sul" }, loot = { 9640, 9639, 9641, 9379 }, tip = { ko = "데카의 방 오른쪽 갈라진 벽 너머 동굴에 있습니다. 바실리스크가 몰려오니 토템부터 부수고 치유를 끊으세요.", en = "In the cave past the cracked wall right of Theka's room. Basilisks pour in: smash his totems first and interrupt his heal." } },
      { id = "s2", n = "2", kind = "boss", quest = true, npc = { 7272 }, name = { ko = "순교자 데카", en = "Theka the Martyr" }, loot = { 10660, 274639, 274638, 274641 }, quests = { 3527, 2936 }, tip = { ko = "체력 30%에 변신해 물리·암흑 피해를 받지 않습니다. 화염·냉기 같은 다른 주문으로 마무리하세요.", en = "At 30% he transforms and ignores physical and shadow damage. Finish him with fire, frost or other spells." } },
      { id = "s3", n = "3", kind = "boss", quest = true, npc = { 7271 }, name = { ko = "의술사 줌라", en = "Witch Doctor Zum'rah" }, loot = { 18082, 18083, 274642 }, quests = { 96770, 96775 }, tip = { ko = "묘지에 있고 다가가면 덤빕니다. 줌라의 수호물 토템부터 부수고 무덤에서 나온 좀비는 광역으로 잡으세요.", en = "In the graveyard; turns hostile when you get close. Break the Ward of Zum'rah totem first and AoE the zombies." } },
      { id = "s4", n = "4", kind = "boss", quest = true, npc = { 7604 }, name = { ko = "하사관 블라이", en = "Sergeant Bly" }, loot = { 8548, 274646, 274647, 274648 }, quests = { 2768 }, tip = { ko = "사형집행인의 열쇠로 피라미드 위 우리를 열고 계단을 지키세요. 위글리와 먼저 대화한 뒤 블라이에게 말을 걸면 일행이 덤비니 치유사 무르타 그림구트부터 잡으세요.", en = "Open the cages with the Executioner's Key and hold the stairs. Talk to Weegli first; talking to Bly then turns his crew hostile, so kill the healer Murta Grimgut first." } },
      { id = "s5", n = "5", kind = "boss", quest = true, npc = { 7796 }, name = { ko = "네크룸 거트츄어", en = "Nekrum Gutchewer" }, loot = { 9471, 274644, 274645, 274643 }, quests = { 2991 }, tip = { ko = "피라미드 이벤트 마지막에 세즈지즈와 함께 내려옵니다.", en = "Comes down with Sezz'ziz at the end of the pyramid event." } },
      { id = "s6", n = "6", kind = "boss", npc = { 7275 }, name = { ko = "어둠의사제 세즈지즈", en = "Shadowpriest Sezz'ziz" }, loot = { 9470, 9473, 9474, 9475 }, tip = { ko = "네크룸을 치유하니 치유를 끊으며 네크룸부터 잡으세요. 영혼의 절규가 있으니 치유사는 떨어져 서세요.", en = "Heals Nekrum: interrupt the heals and kill Nekrum first. Healers stand back from Psychic Scream." } },
      { id = "s7", n = "7", kind = "boss", quest = true, npc = { 7795 }, name = { ko = "유체술사 벨라타", en = "Hydromancer Velratha" }, loot = { 9234, 10661, 274653, 274651, 274652 }, quests = { 2846, 3527 }, tip = { ko = "가즈릴라 연못가에 있습니다. 치유의 물결을 끊고 줌라의 수호물 토템은 바로 부수세요.", en = "By Gahz'rilla's pool. Interrupt Healing Wave and break the Ward of Zum'rah totem at once." } },
      { id = "s8", n = "8", kind = "boss", quest = true, optional = true, npc = { 7273 }, name = { ko = "가즈릴라", en = "Gahz'rilla" }, loot = { 9467, 9469, 274657 }, quests = { 2770 }, tip = { ko = "연못 끝 징을 줄파락의 나무망치로 치면 물에서 올라옵니다. 고체 빙결로 한 명을 얼리고 가즈릴라 격돌로 주위를 날려 보내니, 낙하 피해를 줄이려면 벽에 붙거나 물에 들어가 싸우세요.", en = "Strike the gong at the end of the pool with the Mallet of Zul'Farrak and he rises from the water. Freeze Solid stuns one player and Gahz'rilla Slam throws everyone nearby: fight against a wall or in the water to soften the fall." } },
      { id = "s9", n = "9", kind = "boss", npc = { 7797 }, name = { ko = "루즐루", en = "Ruuzlu" }, loot = { 9523 }, tip = { ko = "꼭대기에서 족장 우코르즈 곁에 붙어 함께 덤빕니다. 회전베기를 쓰니 탱커만 앞에 두고 루즐루부터 잡으세요.", en = "Stands with Chief Ukorz at the top and joins his fight. He uses Cleave: only the tank in front, and kill Ruuzlu first." } },
      { id = "s10", n = "10", kind = "boss", quest = true, npc = { 7267 }, name = { ko = "족장 우코르즈 샌드스칼프", en = "Chief Ukorz Sandscalp" }, loot = { 9476, 9477, 9479, 9478, 11086 }, quests = { 3042 }, tip = { ko = "위글리가 폭파한 문 너머 꼭대기에 루즐루와 함께 있습니다. 루즐루부터 잡고 정면을 피하세요.", en = "At the top past the door Weegli blows open, with Ruuzlu. Kill Ruuzlu first and stay out of his front." } },
      { id = "s11", n = "", kind = "rare", optional = true, npc = { 10082 }, name = { ko = "제릴리스", en = "Zerillis" }, loot = { 12470, 274658 }, tip = { ko = "도시 안을 돌아다니는 희귀 몹입니다.", en = "Rare that patrols the city." } },
