    steps = {
      { id = "s1", n = "1", kind = "boss", quest = true, npc = { 13282 }, name = { ko = "녹시온", en = "Noxxion" }, loot = { 17744, 17746, 17745 }, quests = { 7044 }, tip = { ko = "모습을 감출 때 나오는 녹시온의 피조물부터 잡고 맹독은 해제하세요. 셀레브리안 마법봉을 떨굽니다.", en = "When he vanishes, kill Noxxion's Spawns first and cure the poison. Drops the Celebrian Rod." } },
      { id = "s2", n = "2", kind = "boss", npc = { 12258 }, name = { ko = "칼날채찍", en = "Razorlash" }, loot = { 17748, 17749, 17750, 17751 }, tip = { ko = "회전베기가 탱커 옆 사람까지 치니 탱커만 앞에 두세요. 꿰뚫기 출혈이 걸린 사람은 치유로 챙깁니다.", en = "Cleave also hits whoever stands next to the tank, so only the tank in front. Heal through the Puncture bleed." } },
