      { id = "s4", n = "", kind = "rare", optional = true, npc = { 12237 }, name = { ko = "정원사 메슬로크", en = "Meshlok the Harvester" }, loot = { 17767, 17741, 17742 }, tip = { ko = "맹독 폭포 위쪽을 돌아다니는 희귀 몹입니다. 지나쳐도 됩니다.", en = "Rare roaming above Poison Falls; safe to skip." } },
      { id = "s5", n = "4", kind = "boss", quest = true, npc = { 12225 }, name = { ko = "저주받은 셀레브라스", en = "Celebras the Cursed" }, loot = { 17738, 17739, 17740 }, quests = { 7046, 7044 }, tip = { ko = "맹독 폭포의 우두머리. 타락한 자연의 군대로 부른 나무정령보다 본체를 먼저 치고 천벌은 끊으세요. 처치 후 회복된 셀레브라스에게 셀레브리안 마법봉·다이아몬드를 주고 의식을 지키면 셀레브라스의 홀을 받습니다.", en = "Boss of Poison Falls. Burn him rather than the treants from Corrupt Forces of Nature, and interrupt Wrath. Afterwards give Celebras the Redeemed the Celebrian Rod and Diamond and guard his ritual for the Scepter of Celebras." } },
      { id = "s6", n = "5", kind = "boss", optional = true, npc = { 12203 }, name = { ko = "산사태", en = "Landslide" }, loot = { 17943, 17736, 17737, 17734 }, tip = { ko = "탱커는 벽을 등지고 날려버리기를 버티세요. 파편 소환이 주위를 기절시키며 테라드림 파편을 부르니 광역으로 정리합니다. 길에서 벗어난 비탈 위라 건너뛰어도 됩니다.", en = "Tank with your back to a wall against Knock Away. Summon Shardlings stuns those around him and brings Theradrim Shardlings: AoE them. He is off the main path, so skippable." } },
      { id = "s7", n = "6", kind = "boss", npc = { 13601 }, name = { ko = "땜장이 기즐록", en = "Tinkerer Gizlock" }, loot = { 17717, 17718, 17719 }, tip = { ko = "고블린 용기총이 앞쪽에 불을 뿜으니 탱커만 정면에 두세요.", en = "Goblin Dragon Gun breathes fire forward; only the tank in front." } },
      { id = "s8", n = "7", kind = "boss", optional = true, npc = { 13596 }, name = { ko = "썩은아귀", en = "Rotgrip" }, loot = { 17732, 17728, 17730 }, tip = { ko = "공주의 단 아래 물속에 있는 악어. 뭍으로 끌어내 잡고, 출혈은 치유로 버티세요.", en = "Crocolisk in the water below Theradras's platform; pull it onto land and heal through the bleed." } },
      { id = "s9", n = "8", kind = "boss", quest = true, npc = { 12201 }, name = { ko = "공주 테라드라스", en = "Princess Theradras" }, loot = { 17713, 17714, 17707, 17715, 17766, 17710, 17711, 17780 }, quests = { 7064, 7065, 7066 }, tip = { ko = "매정한 응시에 걸린 한 명은 마비되고 주변 사람은 공포로 달아나니 대비하세요. 처치하면 재타르의 영혼이 나타납니다.", en = "Repulsive Gaze paralyzes one player and sends those nearby fleeing: be ready for fear. Zaetar's Spirit appears after the kill." } },
    },
