    steps = {
      { id = "s2", n = "1", kind = "boss", quest = true, npc = { 255997 }, name = { ko = "해일여제 카자스", en = "Tidemistress Ca'zass" }, aliases = { "Gezeitenherrin Ca'zass", "Maîtresse des marées Ca’zass", "Maestra de las mareas Ca'zass", "Повелительница приливов Ка'засс", "海潮主母卡扎斯", "卡薩絲小姐" }, loot = { 276735, 276736, 276737, 273883 }, quests = { 96381, 96332 }, tip = { ko = "첫 우두머리, 서쪽 둥근 방. 스트라샤즈 요술사 둘과 함께 나오며 셋 모두 연발 얼음 화살과 변이를 쓰니 끊어 주고, 눈보라 장판은 바로 벗어나세요.", en = "First boss, in the round room to the west, with two Strashaz Enchantresses. All three cast Frostbolt Volley and Polymorph: interrupt them. Step out of Blizzard at once." } },
      { id = "s1", n = "2", kind = "boss", quest = true, npc = { 255391 }, name = { ko = "감독관 렉스", en = "Overseer Wrex" }, aliases = { "Aufseher Wrex", "Surveillant Wrex", "Sobrestante Wrex", "Надзиратель Рекс", "狱监雷克斯", "監督者瑞克斯" }, loot = { 276733, 276734, 276732 }, quests = { 96334 }, tip = { ko = "남쪽 감방 구역을 순찰합니다. 걸리면 근처 감방 몹을 모두 부르니 감방부터 비우세요. 떨어뜨리는 열쇠 꾸러미로 입구 오른쪽 잠긴 방을 엽니다.", en = "Patrols the southern cell blocks and calls the nearby cells when pulled: clear them first. Drops the keyring for the locked room right of the entrance." } },
      { id = "s4", n = "3", kind = "boss", quest = true, npc = { 256236 }, name = { ko = "심문관", en = "The Questioner" }, aliases = { "Der Verhörer", "L’Interrogateur", "El Interrogador", "Дознаватель", "质问者", "審問者" }, loot = { 276742, 276743, 276741, 274029 }, quests = { 96334, 96335 }, tip = { ko = "입구 오른쪽 잠긴 둥근 방(감독관 렉스의 열쇠). 부하부터 잡고 생명력 흡수는 차단하세요.", en = "The locked round room right of the entrance (Overseer Wrex's keyring). Adds first; interrupt Drain Life." } },
      { id = "s3", n = "4", kind = "boss", quest = true, npc = { 257016 }, name = { ko = "청소부 카테리나", en = "Katerina the Cleaner" }, aliases = { "Katerina die Aufräumerin", "Katerina la Nettoyeuse", "Katerina la Limpiadora", "Катерина Чистильщица", "清道夫卡特琳娜", "『清潔者』卡特莉娜" }, loot = { 276739, 276740, 276738 }, quests = { 95309, 96334 }, tip = { ko = "아래층 최고 보안 시설, 해일여제 방 바로 아래. 알카즈 전도사 둘부터 잡으세요. 원거리 뒤로 그림자 밟기를 한 뒤 기습하지만 피해는 약합니다.", en = "Lower level (Maximum Security), right below the Tidemistress's room. Kill the two Alcaz chaplains first. She shadowsteps behind ranged players and ambushes them, but hits lightly." } },
