      { id = "s8", n = "3", kind = "boss", quest = true, npc = { 5719, 5722 }, name = { ko = "몰파즈와 하자스", en = "Morphaz and Hazzas" }, loot = { 12465, 12466, 12243, 12464, 10797, 12463, 10795, 10796, 20025 }, quests = { 8232, 8253, 8257, 8236 }, tip = { ko = "꿈꾸는 자의 방 통로를 지키는 용 둘. 숨결 때문에 정면을 돌리세요.", en = "Two dragons guarding the way to the Dreamer's chamber; turn them away for the breath." } },
      { id = "s9", n = "4", kind = "boss", quest = true, npc = { 5709 }, name = { ko = "에라니쿠스의 사령", en = "Shade of Eranikus" }, loot = { 10829, 10833, 10835, 10836, 10828, 10837, 10847, 10454 }, quests = { 3373 }, tip = { ko = "한 명을 15초 재웁니다(잠든 동안 피해 없음). 탱커가 잠들면 다른 근접이 받습니다. 정수를 떨굽니다.", en = "Sleeps one player for 15 sec (no damage while asleep); another melee holds him if the tank sleeps. Drops his essence." } },
