      { id = 8232, level = 52, minLevel = 50, name = { ko = "녹색 비룡 몰파즈", en = "The Green Drake" }, giver = { ko = "몰파즈의 이빨을 아즈샤라의 오그틴크에게(사냥꾼).", en = "Tooth of Morphaz to Ogtinc in Azshara (hunter)." } },
      { id = 8253, level = 52, minLevel = 50, name = { ko = "몰파즈 처치", en = "Destroy Morphaz" }, giver = { ko = "몰파즈를 잡고 대마법사 실렘에게(마법사).", en = "Kill Morphaz and report to Archmage Xylem (mage)." } },
      { id = 8257, level = 52, minLevel = 50, name = { ko = "몰파즈의 피", en = "Blood of Morphaz" }, giver = { ko = "몰파즈의 피를 악령의 숲의 그레타 모스후프에게(사제).", en = "Blood of Morphaz to Greta Mosshoof in Felwood (priest)." } },
      { id = 8236, level = 52, minLevel = 50, name = { ko = "하늘색 열쇠", en = "The Azure Key" }, giver = { ko = "몰파즈에게서 얻은 하늘색 열쇠를 조라크 라벤홀트 경에게(도적).", en = "The Azure Key from Morphaz to Lord Jorach Ravenholdt (rogue)." } },
    },
