    notes = { { ko = "발코니 트롤 6명을 잡아야 잠말란에게 갈 수 있습니다.", en = "Kill the six balcony trolls to reach Jammal'an." }, { ko = "아탈알라리온은 맨 아래층 석상을 순서대로 눌러야 나옵니다.", en = "Atal'alarion appears only after the bottom-floor statues are clicked in order." } },
