  {
    key = "brd", slug = "blackrock-depths", levels = "52-60",
    name = { ko = "검은바위 나락", en = "Blackrock Depths", de = "Schwarzfelstiefen", fr = "Profondeurs de Rochenoire", es = "Profundidades de Roca Negra", ru = "Глубины Черной горы", zhCN = "黑石深渊", zhTW = "黑石深淵" },
    instanceIDs = { 230 }, nameMatch = { "검은바위 나락", "Blackrock Depths", "Глубины Черной горы", "黑石深渊", "黑石深淵" },
    entrance = { map = 1428, x = 29.0, y = 38.0, zone = { ko = "검은바위 산 안쪽 아래(불타는 평원 북서쪽에서 입장)", en = "Deep inside Blackrock Mountain (enter from northwest Burning Steppes)" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 9018 }, name = { ko = "대심문관 게르스탄", en = "High Interrogator Gerstahn" }, loot = { 11624, 11625, 11626, 22240, 11140 }, tip = { ko = "감금 구역 남쪽 방. 마나 연소를 끊고 공포에 대비하세요. 석실 감옥 열쇠를 떨굽니다.", en = "South room of the Detention Block. Interrupt Mana Burn, prepare for fear. Drops the Prison Cell Key." } },
      { id = "s2", n = "", kind = "npc", quest = true, optional = true, npc = { 9023 }, name = { ko = "치안대장 윈저", en = "Marshal Windsor" }, quests = { 4322, 4264, 4241, 4242, 4282 }, tip = { ko = "감방에 갇혀 있습니다. 풀어 주면 긴 호위가 시작됩니다(얼라이언스 탈옥!).", en = "Locked in a cell; freeing him starts a long escort (Alliance Jail Break!)." } },
      { id = "s3", n = "", kind = "npc", quest = true, optional = true, npc = { 9020 }, name = { ko = "사령관 고르샤크", en = "Commander Gor'shak" }, quests = { 3981, 3982, 4001 }, tip = { ko = "감방에 갇혀 있습니다. 풀어 주면 몰려오는 드워프를 막아야 합니다(호드).", en = "Locked in a cell; free him and hold off the dwarves (Horde)." } },
      { id = "s4", n = "2", kind = "boss", npc = { 9025 }, name = { ko = "불의 군주 록코르", en = "Lord Roccor" }, loot = { 11632, 11631, 22234, 22397, 11630 }, tip = { ko = "법의 심판장 북쪽 둘레를 돕니다. 지진이 가까이 있는 사람을 모두 기절시키니 원거리는 거리를 두세요.", en = "Patrols the north side of the Ring of Law. Ground Tremor stuns everyone close to him, so ranged keep their distance." } },
      { id = "s5", n = "3", kind = "boss", npc = { 9319 }, name = { ko = "사냥개조련사 그렙마르", en = "Houndmaster Grebmar" }, loot = { 11627, 11623, 11628, 11629 }, tip = { ko = "통로 가장 낮은 곳. 사냥개부터 잡으세요.", en = "Lowest part of the passage; kill the hounds first." } },
      { id = "s6", n = "4", kind = "boss", quest = true, npc = { 9027, 9028, 9029, 9030, 9031, 9032 }, name = { ko = "법의 심판장", en = "Ring of Law" }, loot = { 22271, 22257, 22266, 11726, 11610, 11722, 11703, 11702, 11728, 11675, 11677, 11635, 11729 }, quests = { 9015 }, tip = { ko = "투기장 가운데로 가면 문이 닫히고 짐승 두 무리 뒤에 투사 하나가 무작위로 나옵니다. 이기면 동쪽 문이 열립니다.", en = "Step into the arena: the gates close, two beast waves, then a random champion. Winning opens the east gate." } },
      { id = "s9", n = "7", kind = "boss", npc = { 9024 }, name = { ko = "화염술사 로어그레인", en = "Pyromancer Loregrain" }, loot = { 11747, 11748, 11749, 11750 }, tip = { ko = "석상 앞에 무릎 꿇고 있습니다. 토템을 바로 부수세요.", en = "Kneels before the statue; smash his totems at once." } },
      { id = "s7", n = "5", kind = "boss", quest = true, npc = { 9017 }, name = { ko = "불의 군주 인센디우스", en = "Lord Incendius" }, loot = { 11764, 11765, 11766, 11767, 19268, 11768 }, quests = { 4263, 3907 }, tip = { ko = "검은 모루 앞을 지킵니다. 강력한 일격에 밀려나지 않게 탱커는 벽을 등지고, 정령 군주의 저주는 바로 해제하세요. 불폭풍이 땅에 떨어지니 원거리는 모여 서지 마세요.", en = "Guards the Black Anvil. The tank backs onto a wall against Mighty Blow; remove Curse of the Elemental Lord quickly. Fire Storm hits an area, so ranged don't bunch up." } },
      { id = "s8", n = "6", kind = "boss", quest = true, npc = { 9056 }, name = { ko = "파이너스 다크바이어", en = "Fineous Darkvire" }, loot = { 11841, 11842, 11839, 22223, 11840 }, quests = { 3802 }, tip = { ko = "성스러운 빛으로 스스로를 치유하니 꼭 끊으세요. 장인의 전당 비탈을 오가며, 기념비에 올릴 무쇠지옥을 떨굽니다.", en = "Interrupt every Holy Light, his self-heal. He walks the Hall of Crafting ramp and drops Ironfel for the monument." } },
      { id = "s10", n = "8", kind = "object", quest = true, npc = {  }, name = { ko = "프랑클론 포지라이트의 기념비", en = "Monument of Franclorn Forgewright" }, quests = { 3802 }, tip = { ko = "무쇠지옥을 올리면 어둠괴철로단 열쇠를 받습니다. 도시 안쪽의 잠긴 큰 문들을 엽니다.", en = "Place Ironfel here for the Shadowforge Key; it opens the locked gates deeper in the city." } },
      { id = "s11", n = "", kind = "boss", optional = true, npc = { 9041, 9042 }, name = { ko = "문지기 스틸기스와 베레크", en = "Warder Stilgiss and Verek" }, loot = { 11782, 11783, 11784, 22241, 11755, 22242 }, tip = { ko = "검은 금고. 스틸기스부터 잡고, 냉기 주문은 쓰지 마세요.", en = "The Black Vault; kill Stilgiss first and avoid frost spells." } },
      { id = "s12", n = "", kind = "task", quest = true, optional = true, npc = {  }, name = { ko = "검은 금고", en = "The Black Vault" }, quests = { 4123 }, tip = { ko = "던전 드워프가 떨구는 유물 금고 열쇠로 금고 12개를 모두 여세요. 깨어난 둠그립과 골렘을 잡으면 산의 정수를 꺼냅니다.", en = "Open all 12 coffers with Relic Coffer Keys from the dwarves here. Kill Doomgrip and the golems, then take the Heart of the Mountain." } },
      { id = "s13", n = "", kind = "boss", quest = true, optional = true, npc = { 9016 }, name = { ko = "밸가르", en = "Bael'Gar" }, loot = { 11802, 11803, 11805, 11807 }, quests = { 4024 }, tip = { ko = "대로 서쪽 끝. 용암을 피해 모두 뒤에 서고, 용암 덩어리를 먼저 잡으세요.", en = "West end of the highway; stand behind him away from lava, kill the lava adds first." } },
      { id = "s14", n = "9", kind = "boss", quest = true, npc = { 9033 }, name = { ko = "사령관 앵거포지", en = "General Angerforge" }, loot = { 11816, 11820, 11821, 11817, 11810 }, quests = { 4132, 4282 }, tip = { ko = "서부 주둔지 계단 아래 방에 있습니다. 비탈 위에서 원거리로 끌어 옆방이 딸려 오지 않게 하고, 체력이 낮을 때 성난모루단 지원군이 몰려오니 그 전에 몰아쳐 끝내세요.", en = "Below the stairs of the West Garrison. Pull him from the ramp with a ranged attack so the next room stays put; Anvilrage reinforcements arrive when he is low, so burst him before that." } },
      { id = "s15", n = "10", kind = "boss", quest = true, npc = { 8983 }, name = { ko = "골렘 군주 아젤마크", en = "Golem Lord Argelmach" }, loot = { 11822, 11823, 11669, 11819 }, quests = { 4063, 4282 }, tip = { ko = "함께 깨어나는 골렘부터. 번개 보호막 때문에 근접은 조심, 연쇄 번개를 끊으세요.", en = "Golems first. His lightning shield hurts melee; interrupt Chain Lightning." } },
      { id = "s16", n = "", kind = "boss", quest = true, optional = true, npc = { 9537 }, name = { ko = "헐레이 블랙브레스", en = "Hurley Blackbreath" }, loot = { 18044, 18043, 22275, 11735 }, quests = { 4126, 4134 }, tip = { ko = "선술집 안쪽 맥주통 셋을 깨면 친구들과 나옵니다. 손님이 맞지 않게 구석에서.", en = "Break the three casks in the tavern; he comes with friends. Fight in a corner away from patrons." } },
      { id = "s17", n = "", kind = "boss", quest = true, optional = true, npc = { 9543 }, name = { ko = "리블리 스크류스피곳", en = "Ribbly Screwspigot" }, loot = { 2662, 2663, 11742 }, quests = { 4136 }, tip = { ko = "평소 우호적. 대화로 위협하면 패거리와 덤빕니다.", en = "Friendly until you threaten him in dialogue; then he and his gang attack." } },
      { id = "s18", n = "11", kind = "npc", quest = true, npc = { 9503 }, name = { ko = "병사 락노트", en = "Private Rocknot" }, quests = { 4295 }, tip = { ko = "검은무쇠 에일 맥주잔(플러거 판매)을 몇 번 건네세요. 팔란스가 깨어나 마법의 방 쪽 문을 부숩니다.", en = "Give him Dark Iron Ale Mugs (sold by Plugger) a few times; Phalanx wakes and breaks the door to the Chamber of Enchantment." } },
      { id = "s19", n = "12", kind = "boss", npc = { 9502 }, name = { ko = "팔란스", en = "Phalanx" }, loot = { 11745, 11744, 22212, 11743 }, tip = { ko = "선술집 문을 부수고 나옵니다. 연발 화염구가 파티 전체를 태우니 체력을 늘 채워 두고, 원거리는 천둥벼락 범위 밖에 서세요. 강력한 일격은 탱커를 밀쳐냅니다.", en = "Bursts through the tavern door. Fireball Volley hits the whole group, so stay topped off; ranged stand outside Thunderclap, and Mighty Blow knocks the tank back." } },
      { id = "s20", n = "", kind = "boss", optional = true, npc = { 9499 }, name = { ko = "플러거 스파즈링", en = "Plugger Spazzring" }, loot = { 12793, 12791, 11602 }, tip = { ko = "공격하면 선술집 손님 모두가 적대하니 빈 곳으로 끌어 잡으세요. 제물과 언어의 저주는 바로 해제합니다.", en = "Attacking him turns the whole tavern hostile, so pull him to an empty spot. Dispel Immolate and remove Curse of Tongues." } },
      { id = "s21", n = "", kind = "npc", quest = true, optional = true, npc = { 9500 }, name = { ko = "지배인 나그마라", en = "Mistress Nagmara" }, quests = { 4201 }, tip = { ko = "선술집 2층. 사랑의 묘약 퀘스트.", en = "Tavern upstairs; The Love Potion." } },
      { id = "s22", n = "", kind = "npc", quest = true, optional = true, npc = { 12944 }, name = { ko = "로크토스 다크바게이너", en = "Lokhtos Darkbargainer" }, quests = { 7604 }, tip = { ko = "선술집에 있는 토륨 대장조합 상인입니다. 평판 물품을 팔고, 토륨 대장조합 계약서를 건네면 도면: 설퍼론 망치를 줍니다.", en = "Thorium Brotherhood vendor in the tavern. Sells reputation goods; hand him the Thorium Brotherhood Contract for Plans: Sulfuron Hammer." } },
      { id = "s23", n = "13", kind = "boss", npc = { 9156 }, name = { ko = "사자 화염채찍", en = "Ambassador Flamelash" }, loot = { 11812, 11814, 11809, 11832, 11808 }, tip = { ko = "둘레 룬에서 나오는 불타는 정령이 닿으면 강해지니 원거리가 미리 잡으세요.", en = "Burning spirits from the runes empower him; ranged kill them before they arrive." } },
      { id = "s24", n = "14", kind = "boss", npc = { 9034, 9035, 9036, 9037, 9038, 9039, 9040 }, name = { ko = "일곱 현자", en = "The Seven" }, loot = { 11920, 11921, 11922, 11926, 11927, 11923, 11925, 11929 }, tip = { ko = "운명의 문지기에게 말을 걸면 하나씩 덤빕니다. 사이사이 마나를 채우세요. 끝나면 상자가 나옵니다.", en = "Talk to Doom'rel; they come one at a time. Drink between them. A chest appears at the end." } },
      { id = "s25", n = "", kind = "object", quest = true, optional = true, npc = {  }, name = { ko = "유령의 성배", en = "The Spectral Chalice" }, quests = { 4083 }, tip = { ko = "채광 230 이상이면 그늘의 문지기에게 말을 걸고 별루비 2·금괴 20·진은 주괴 10개를 바쳐 검은무쇠 제련을 배웁니다.", en = "Mining 230+: talk to Gloom'rel and offer 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars to learn Smelt Dark Iron." } },
      { id = "s26", n = "15", kind = "task", npc = {  }, name = { ko = "훈련강당 화로", en = "Lyceum braziers" }, tip = { ko = "불꽃지기가 떨구는 횃불로 화로 둘에 불을 붙이면 철의 전당 문이 열립니다.", en = "Light both braziers with torches from the Flamekeepers to open the Iron Hall." } },
      { id = "s27", n = "16", kind = "boss", npc = { 9938 }, name = { ko = "마그무스", en = "Magmus" }, loot = { 11746, 11935, 22208, 22395, 22400, 277129 }, tip = { ko = "양옆 석상의 불길을 피하고 오른쪽 구석으로 끌어 잡으세요.", en = "Dodge the statues' fire; pull him to the right corner." } },
      { id = "s28", n = "17", kind = "boss", quest = true, npc = { 9019, 8929 }, name = { ko = "제왕 다그란 타우릿산", en = "Emperor Dagran Thaurissan" }, loot = { 11815, 11924, 11928, 11930, 11931, 11932, 11933, 11934, 22204, 22207, 11684, 12033 }, quests = { 4362, 4003, 4363, 4004 }, tip = { ko = "공주가 제왕을 치유하니 끊으세요. 공주 구출 퀘스트면 공주는 살려 두고 제왕만 잡습니다.", en = "The princess heals him; interrupt her. On the rescue quest keep her alive and kill only him." } },
      { id = "s29", n = "", kind = "object", quest = true, optional = true, npc = {  }, name = { ko = "핵 조각", en = "Core Fragment" }, quests = { 7848 }, tip = { ko = "작열하는 다리 끝, 화산 심장부 차원문 옆. 화산 심장부 입장 퀘스트.", en = "End of the bridge by the Molten Core portal; attunement quest." } },
      { id = "s30", n = "", kind = "rare", optional = true, npc = { 8923 }, name = { ko = "무적의 판저", en = "Panzor the Invincible" }, loot = { 11787, 11786, 11785, 22245 }, tip = { ko = "가끔 나타나는 희귀 골렘.", en = "Rare golem that does not always spawn." } },
    },
    quests = {
      { id = 3801, level = 52, minLevel = 48, name = { ko = "검은무쇠 유물", en = "Dark Iron Legacy" }, giver = { ko = "검은바위 산 한가운데의 프랑클론 포지라이트와 대화(유령일 때만 보임).", en = "Talk to Franclorn Forgewright in the middle of Blackrock Mountain (visible only as a ghost)." } },
      { id = 3802, level = 52, minLevel = 48, name = { ko = "검은무쇠 유물", en = "Dark Iron Legacy" }, giver = { ko = "파이너스가 떨군 무쇠지옥을 프랑클론 포지라이트의 기념비에 올리기.", en = "Place Fineous's Ironfel on the Monument of Franclorn Forgewright." } },
      { id = 3907, faction = "Horde", level = 56, minLevel = 48, name = { ko = "불의 부조화", en = "Disharmony of Fire" }, giver = { ko = "인센디우스를 처치하고 서판을 썬더하트에게.", en = "Kill Incendius; bring the tablet to Thunderheart." } },
      { id = 3981, faction = "Horde", level = 52, minLevel = 48, name = { ko = "사령관 고르샤크", en = "Commander Gor'shak" }, giver = { ko = "감옥에 갇힌 고르샤크 사령관 찾기.", en = "Find Commander Gor'shak in the prison." } },
      { id = 3982, faction = "Horde", level = 54, minLevel = 48, name = { ko = "사태 파악", en = "What Is Going On?" }, giver = { ko = "고르샤크를 지켜 습격을 버티기.", en = "Defend Gor'shak from the onslaught." } },
      { id = 4003, faction = "Horde", level = 59, minLevel = 48, name = { ko = "공주 구출", en = "The Royal Rescue" }, giver = { ko = "제왕을 처치하고 모이라 공주를 구출.", en = "Kill the Emperor and free Princess Moira." } },
      { id = 4081, faction = "Horde", level = 52, minLevel = 48, name = { ko = "죽음의 본보기: 검은무쇠 드워프", en = "KILL ON SIGHT: Dark Iron Dwarves" }, giver = { ko = "성난모루단 보초·교도관·보병을 처치하고 카르가스의 고어투스에게.", en = "Kill Anvilrage Guardsmen, Wardens and Footmen; report to Goretooth in Kargath." } },
      { id = 4082, faction = "Horde", level = 54, minLevel = 50, name = { ko = "죽음의 본보기: 검은무쇠 부족 고위 관리", en = "KILL ON SIGHT: High Ranking Dark Iron Officials" }, giver = { ko = "성난모루단 간호병·병사·장교를 처치하고 고어투스에게.", en = "Kill Anvilrage Medics, Soldiers and Officers; report to Goretooth." } },
      { id = 4132, faction = "Horde", level = 58, minLevel = 52, name = { ko = "앵거포지 척살 작전", en = "Operation: Death to Angerforge" }, giver = { ko = "앵거포지를 처치하고 고어투스에게.", en = "Kill Angerforge; report to Goretooth." } },
