      { id = 7201, faction = "Horde", level = 54, minLevel = 48, name = { ko = "마지막 원소", en = "The Last Element" }, giver = { ko = "골렘·정령이 떨구는 원소의 정수 10개를 비비안 라그레이브에게.", en = "10 Essence of the Elements (golems, elementals) to Vivian Lagrave." } },
      { id = 97197, faction = "Horde", level = 55, minLevel = 46, name = { ko = "불의 땅의 파편", en = "Fragment of the Firelands" }, giver = { ko = "불의 땅 파편을 멀고어의 알라나 스톰워커에게.", en = "A Fragment of the Firelands to Alaana Stormwalker in Mulgore." } },
      { id = 4241, faction = "Alliance", level = 54, minLevel = 48, name = { ko = "치안대장 윈저", en = "Marshal Windsor" }, giver = { ko = "나락에 갇힌 윈저 치안대장 찾기.", en = "Find Marshal Windsor in the prison." } },
