      { id = 4282, faction = "Alliance", level = 58, minLevel = 50, name = { ko = "잔존하는 희망", en = "A Shred of Hope" }, giver = { ko = "아젤마크와 앵거포지가 가진 윈저의 정보를 되찾기.", en = "Recover Windsor's notes from Argelmach and Angerforge." } },
      { id = 4322, faction = "Alliance", level = 58, minLevel = 50, name = { ko = "탈옥!", en = "Jail Break!" }, giver = { ko = "윈저 치안대장의 장비를 되찾고 동료를 풀어주기.", en = "Help Windsor recover his gear and free his friends." } },
