      { id = 4126, faction = "Alliance", level = 55, minLevel = 50, name = { ko = "헐레이 블랙브레스", en = "Hurley Blackbreath" }, giver = { ko = "썬더브루 제조법을 카라노스의 라그나르에게.", en = "Thunderbrew recipe to Ragnar in Kharanos." } },
      { id = 4286, faction = "Alliance", level = 56, minLevel = 50, name = { ko = "좋은 물건", en = "The Good Stuff" }, giver = { ko = "검은무쇠 벨트주머니 20개를 랄리우스에게.", en = "20 Dark Iron Fanny Packs to Oralius." } },
      { id = 4362, faction = "Alliance", level = 59, minLevel = 50, name = { ko = "왕국의 운명", en = "The Fate of the Kingdom" }, giver = { ko = "제왕을 처치하고 모이라 공주를 구출.", en = "Kill the Emperor and rescue Princess Moira." } },
      { id = 4024, level = 58, minLevel = 52, name = { ko = "화염의 맛", en = "A Taste of Flame" }, giver = { ko = "밸가르 시체에 변형된 검은용군단 허물을 쓰고 불의 정수를 키루스 테레펜터스에게.", en = "Use the Altered Black Dragonflight Molt on Bael'Gar's corpse; bring the essence to Cyrus Therepentous." } },
      { id = 4123, level = 55, minLevel = 50, name = { ko = "산의 정수", en = "The Heart of the Mountain" }, giver = { ko = "검은 금고 아래 비밀 금고의 산의 정수를 불타는 평원의 맥스워트에게.", en = "The Heart of the Mountain from the Vault's secret safe to Maxwort in the Burning Steppes." } },
      { id = 4136, level = 53, minLevel = 48, name = { ko = "리블리 스크류스피곳", en = "Ribbly Screwspigot" }, giver = { ko = "리블리의 머리카락을 유카 스크류스피곳에게.", en = "Ribbly's Head to Yuka Screwspigot." } },
      { id = 4201, level = 54, minLevel = 50, name = { ko = "사랑의 묘약", en = "The Love Potion" }, giver = { ko = "그롬의 피 4개, 거대한 은 광석 10개, 가득 찬 나그마라의 약병을 나그마라에게.", en = "4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Nagmara." } },
      { id = 4083, level = 55, minLevel = 40, name = { ko = "유령의 성배", en = "The Spectral Chalice" }, giver = { ko = "그늘의 문지기에게 말을 걸고 별루비 2·금괴 20·진은 주괴 10개를 바쳐 검은무쇠 제련 배우기(채광 230).", en = "Talk to Gloom'rel; offer 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars to learn Smelt Dark Iron (Mining 230)." } },
      { id = 4264, faction = "Alliance", level = 58, minLevel = 50, name = { ko = "꼬깃꼬깃한 쪽지", en = "A Crumpled Up Note" }, giver = { ko = "던전에서 주운 꼬깃꼬깃한 쪽지를 치안대장 윈저에게(실망 다음).", en = "Bring A Crumpled Up Note found in the dungeon to Marshal Windsor (after Abandoned Hope)." } },
      { id = 4001, faction = "Horde", level = 54, minLevel = 48, name = { ko = "사태 파악", en = "What Is Going On?" }, giver = { ko = "건너편 감방의 카란 마이트해머와 대화.", en = "Talk to Kharan Mighthammer in the cell across the hall." } },
      { id = 4128, faction = "Alliance", level = 55, minLevel = 50, name = { ko = "라그나르 썬더브루", en = "Ragnar Thunderbrew" }, giver = { ko = "카라노스의 라그나르 썬더브루와 대화(헐레이 퀘스트 시작).", en = "Talk to Ragnar Thunderbrew in Kharanos (leads to Hurley Blackbreath)." } },
      { id = 4133, faction = "Horde", level = 55, minLevel = 50, name = { ko = "비비안 라그레이브", en = "Vivian Lagrave" }, giver = { ko = "카르가스의 어둠마법사 비비안 라그레이브와 대화(썬더브루 제조법 시작).", en = "Talk to Shadowmage Vivian Lagrave in Kargath (leads to the Thunderbrew recipe)." } },
      { id = 4324, level = 53, minLevel = 48, name = { ko = "유카 스크류스피곳", en = "Yuka Screwspigot" }, giver = { ko = "불타는 평원의 유카 스크류스피곳과 대화(리블리 퀘스트 시작).", en = "Talk to Yuka Screwspigot in the Burning Steppes (leads to Ribbly)." } },
      { id = 4295, level = 1, minLevel = 1, name = { ko = "락노트의 에일 맥주", en = "Rocknot's Ale" }, giver = { ko = "플러거에게 산 검은무쇠 에일 맥주잔을 락노트에게.", en = "Give Rocknot Dark Iron Ale Mugs bought from Plugger." } },
      { id = 7604, level = 60, minLevel = 60, name = { ko = "대장조합 계약서", en = "A Binding Contract" }, giver = { ko = "토륨 대장조합 계약서와 설퍼론 주괴를 로크토스에게(설퍼론 도면).", en = "Thorium Brotherhood Contract and a Sulfuron Ingot to Lokhtos for the Sulfuron plans." } },
      { id = 4363, faction = "Alliance", level = 59, minLevel = 50, name = { ko = "브론즈비어드 공주", en = "The Princess's Surprise" }, giver = { ko = "공주를 구한 뒤 아이언포지의 국왕 마그니 브론즈비어드에게.", en = "After the rescue, return to King Magni Bronzebeard in Ironforge." } },
      { id = 4004, faction = "Horde", level = 60, minLevel = 48, name = { ko = "구출된 공주?", en = "The Princess Saved?" }, giver = { ko = "공주를 구한 뒤 오그리마의 스랄에게.", en = "After the rescue, return to Thrall in Orgrimmar." } },
      { id = 9015, level = 60, minLevel = 58, name = { ko = "도전", en = "The Challenge" }, giver = { ko = "법의 심판장 가운데에 도전의 깃발을 꽂고 텔드렌 무리를 잡아 아뮬렛 첫 조각을 안시온 하몬에게.", en = "Plant the Banner of Provocation in the Ring of Law, beat Theldren's group; first amulet piece to Anthion Harmon." } },
      { id = 7848, level = 60, minLevel = 55, name = { ko = "심장부와의 조화", en = "Attunement to the Core" }, giver = { ko = "화산 심장부 차원문 옆 핵 조각을 검은바위 산의 로소스 리프트웨이커에게.", en = "Core Fragment by the Molten Core portal to Lothos Riftwaker in Blackrock Mountain." } },
