    notes = { { ko = "어둠괴철로단 열쇠(프랑클론 기념비에서 받음)가 있으면 도시 안쪽의 잠긴 큰 문들을 바로 열 수 있습니다.", en = "The Shadowforge Key (from Franclorn's monument) opens the locked gates deeper in the city." }, { ko = "선술집에서 소란을 피우면 술집 전체가 적대합니다.", en = "Causing trouble in the tavern turns everyone hostile." } },
