  {
    key = "blackmaw", slug = "blackmaw-hold", levels = "55-60",
    name = { ko = "검은아귀 요새", en = "Blackmaw Hold", de = "Schwarzschlundfeste", fr = "Repaire des Noiregueules", es = "Bastión Faucenegra", ru = "Крепость Черночревов", zhCN = "黑喉要塞", zhTW = "黑喉要塞" },
    instanceIDs = { 2974 }, nameMatch = { "검은아귀 요새", "Blackmaw Hold", "Крепость Черночревов", "黑喉要塞" },
    entrance = { map = 1447, x = 38.7, y = 33.4, zone = { ko = "아즈샤라 북쪽, 곰 머리가 새겨진 털보 굴. 굴 안쪽 깊은 곳에 차원문", en = "Northern Azshara: the furbolg tunnel with a carved bear head; the portal is deep inside" } },
    steps = {
      { id = "s1", n = "1", kind = "boss", npc = { 247195 }, name = { ko = "마른아귀", en = "Withermaw" }, aliases = { "Welkschlund", "Flétrigueule", "Faucemarchita", "Сухозев", "枯颌", "枯萎之喉" }, loot = { 280063, 280062, 280064 }, tip = { ko = "썩어가는 소굴(동굴) 안. 구더기를 불러내니 탱커가 끌어모으세요. 공포와 질병을 겁니다.", en = "Inside the Festering Grotto (cave). Spawns Flesh Maggots: the tank picks them up. Casts Fear and diseases." } },
      { id = "s2", n = "2", kind = "boss", npc = { 247206 }, name = { ko = "간수 임판", en = "Impaan the Imprisoner" }, aliases = { "Impaan der Kerkermeister", "Diablaan l’Enfermeur", "Diapaan el Diabólico", "Бесаан Бесноватый", "狱牢头鬼", "『小鬼禁錮者』鬼潘" }, loot = { 280057, 280056, 280058 }, tip = { ko = "구불구불한 오르막길 끝 더럽혀진 봉우리의 사티로스. '임프!'로 임프 여럿을 불러내면 불가침으로 받는 피해가 크게 줄어드니 임프부터 잡으세요.", en = "Satyr on the Defiled Peak at the top of the winding uphill path. Imps! calls several imps, and Impervious cuts his damage taken while they live: kill the imps first." } },
      { id = "s3", n = "3", kind = "boss", npc = { 247209 }, name = { ko = "장로 주술사 핏빛갈기", en = "Elder Shaman Bloodmane" }, aliases = { "Schamanenältester Bloodmane", "Ancien chaman crin-de-sang", "Chamán anciano Melenasangre", "Старейшина-шаман Кровогрив", "长者萨满血鬃", "薩滿長老血鬃" }, loot = { 280070, 280069, 280068 }, tip = { ko = "아래쪽 넓은 방. 검은아귀 신도부터 잡으세요. 야수 정령으로 늑대 정령 둘을 부르고 연쇄 번개는 차단하세요. 정화는 끊을 수 없고 기절시키며 강화 효과를 지웁니다.", en = "Wide chamber near the bottom. Kill the Blackmaw Devotees first. Feral Spirit calls two wolves; interrupt Chain Lightning. Purge can't be interrupted: it stuns and strips a buff." } },
      { id = "s4", n = "4", kind = "boss", npc = { 247198 }, name = { ko = "꺾이지 않는 해골주둥이", en = "Bonesnout the Unbroken" }, aliases = { "Knochenschnauze der Ungebrochene", "Muflos l’Indompté", "Morrohueso el Inquebrantable", "Костерыл Несломленный", "不屈的白骨之吻", "『不屈者』骨鼻" }, loot = { 280059, 280060, 280061 }, tip = { ko = "동쪽 덤불을 순찰합니다. 의식술사 넷이 모독으로 불경한 보루를 쌓아 받는 피해를 25%씩 줄여 주니 넷부터 잡고, 주변을 기절시키는 발구르기에 주의하세요.", en = "Patrols his thicket to the east. Four ritualists stack Profane Bulwark on him with Desecration, each cutting his damage taken by 25%: kill them first. His stomp stuns nearby players." } },
      { id = "s5", n = "5", kind = "boss", quest = true, npc = { 247234 }, name = { ko = "바록스 블릭후프", en = "Varrox Bleakhoof" }, aliases = { "Varrox Mornesabot", "Varrox Pezuña Lúgubre", "Варрокс Мутное Копыто", "瓦罗克斯·暗蹄", "瓦洛仕‧荒蹄" }, loot = { 280076, 280075, 280074, 249692 }, quests = { 92065 }, tip = { ko = "거수 뒤 반짝이는 웅덩이로 뛰어내리면 나오는 동굴의 마지막 우두머리. 진홍빛 갈취로 끌려간 사람이 터지며 암흑 피해와 웅덩이를 남기니, 주변은 비키고 탱커는 웅덩이 밖으로 옮기세요.", en = "Final boss, in the cave reached by dropping into the shimmering pool behind the Behemoth. Crimson Wrest drags a player to him, who bursts for shadow damage and leaves a pool: others step away, the tank moves him out of it." } },
      { id = "s6", n = "6", kind = "boss", npc = { 247207 }, name = { ko = "검은아귀 거수", en = "Blackmaw Behemoth" }, aliases = { "Behemoth des Schwarzschlunds", "Béhémoth noiregueule", "Behemoth Faucenegra", "Исполин из клана Черночревов", "黑喉巨兽", "黑喉巨獸" }, loot = { 280065, 280066, 280067 }, tip = { ko = "경사로 지나 오른쪽 방. 클로버트가 회복으로 거수를 가득 채우니 클로버트부터 잡으세요. 그를 삼키면 포효가 강해지니(천둥 포효는 넓게 기절) 야수의 포효와 함께 차단하세요.", en = "Room to the right past the ramp. Clawbert's Restore heals the Behemoth to full, so kill Clawbert first. Once the Behemoth eats him its roars get stronger (Thunder Roar is a wide stun): interrupt them and Bestial Roar." } },
      { id = "s7", n = "7", kind = "boss", npc = { 247231 }, name = { ko = "속박 풀린 영혼", en = "Unbound Spirit" }, aliases = { "Ungebundener Geist", "Esprit délié", "Espíritu desvinculado", "Свободный дух", "不羁之魂", "無縛之靈" }, loot = { 280072, 280073, 280071 }, tip = { ko = "본 구역 남쪽 옆길 안쪽. 처음엔 불경한 토템 셋이 지켜 무적입니다. 장로에게 말을 걸면 순화로 토템을 약하게 만드니, 몰려오는 거미·늑대·곰 정령을 잡으며 토템을 부수세요.", en = "Down the side passage south of the main area. Three Profane Totems keep him invulnerable; talk to the elder, whose Purify makes the totems breakable, then kill the spider, wolf and bear spirits while you smash the totems." } },
      { id = "s8", n = "8", kind = "rare", optional = true, npc = { 269104 }, name = { ko = "달빛에 물든 방랑자", en = "Moontouched Wanderer" }, loot = { 280080, 280079 }, tip = { ko = "해골주둥이 덤불의 남동쪽 끝 구석에 나오는 올빼미야수 희귀 정예입니다. 없을 때가 있습니다.", en = "Rare elite owlbeast in the far south-east corner of Bonesnout's thicket; not always there." } },
      { id = "s9", n = "9", kind = "rare", optional = true, npc = { 269111 }, name = { ko = "수습생 고르텍", en = "Gortek the Apprentice" }, loot = { 280077, 280078 }, tip = { ko = "희귀 정예라 없을 때가 있습니다. 검은아귀 거수 방 옆에서 지옥불 임프를 데리고 나옵니다.", en = "Rare elite, not always there; next to the Blackmaw Behemoth's chamber with Felfire Imps." } },
      { id = "s10", n = "10", kind = "rare", optional = true, npc = { 250034 }, name = { ko = "땅굴그물 어미", en = "Tunnelweb Matriarch" }, loot = { 280085, 280086 }, tip = { ko = "희귀 정예라 없을 때가 있습니다. 썩어가는 소굴 안에 나오며, 지도 표시는 대략적인 자리입니다.", en = "Rare elite; not always there. Found in the Festering Grotto; the map mark is only an estimate." } },
    },
    quests = {
      { id = 92344, faction = "Alliance", level = 55, minLevel = 45, name = { ko = "뿌리를 찾아서", en = "Get to the Roots of It" }, giver = { ko = "검은아귀 요새에서 놀드랏실 뿌리 버섯 10개를 채집해 다르나서스에 있는 마스렌길 베어워커에게 전달해야 합니다.", en = "Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Mathrengyl Bearwalker in Darnassus." } },
      { id = 97173, faction = "Alliance", level = 59, minLevel = 52, name = { ko = "검은아귀 마법", en = "Blackmaw Magic" }, giver = { ko = "검은아귀 요새에서 검은아귀 의식 토템을 회수해야 합니다.", en = "Recover a Blackmaw Ritual Totem from Blackmaw Hold." } },
