    steps = {
      { id = "s1", n = "", kind = "boss", quest = true, optional = true, npc = { 10506 }, name = { ko = "사자 키르토노스", en = "Kirtonos the Herald" }, loot = { 13960, 13967, 13969, 14024, 13957, 16734, 13955, 13956, 13983 }, quests = { 5384 }, tip = { ko = "현관 화롯불에 순결한 피를 올리면 날아옵니다. 저주를 풀고 지배당한 사람은 제어하세요.", en = "Put the Blood of Innocents on the porch brazier to call him. Decurse and control the mind-controlled." } },
      { id = "s2", n = "1", kind = "boss", quest = true, npc = { 10503 }, name = { ko = "잔다이스 바로브", en = "Jandice Barov" }, loot = { 16701, 14545, 14541, 14548, 18690, 18689, 22394, 13523, 14543 }, quests = { 5515 }, tip = { ko = "사라졌다가 환영을 여럿 부릅니다. 광역으로 환영을 지우고 진짜를 잡으세요.", en = "Vanishes and summons illusions; AoE them away and kill the real one." } },
      { id = "s3", n = "2", kind = "boss", npc = { 11622 }, name = { ko = "들창어금니", en = "Rattlegore" }, loot = { 16711, 14528, 14531, 14537, 14538, 14539, 18686, 18782, 13873 }, tip = { ko = "근접을 기절시키고 탱커를 밀어냅니다. 강당 열쇠를 떨굽니다.", en = "Stuns melee and knocks the tank back. Drops the key to the hall." } },
      { id = "s4", n = "3", kind = "boss", quest = true, npc = { 10433, 10432 }, name = { ko = "마르두크 블랙풀과 벡투스", en = "Marduk Blackpool and Vectus" }, loot = { 14576, 18692, 14577, 18691 }, quests = { 4771 }, tip = { ko = "강당의 두 우두머리. 벡투스의 불기둥은 시전을 끊거나 장판에서 비키고, 마르두크의 연발 어둠의 화살은 즉시 시전이라 치유로 버팁니다. '여명의 계략'은 계략을 강당에 놓은 뒤 벡투스를 잡습니다.", en = "The pair in the Viewing Room. Interrupt or step out of Vectus's Flamestrike; Marduk's Shadow Bolt Volley is instant, so heal through it. For Dawn's Gambit, place it in the room, then kill Vectus." } },
      { id = "s5", n = "4", kind = "boss", quest = true, npc = { 10508 }, name = { ko = "라스 프로스트위스퍼", en = "Ras Frostwhisper" }, loot = { 16689, 14487, 14502, 18694, 18696, 13952, 14340, 14522, 14525, 18693, 13314, 14503, 18695 }, quests = { 5466 }, tip = { ko = "강당 남쪽 연구소. 연발 얼음 화살을 끊으세요. 퀘스트면 먼저 유품을 써서 사람으로 되돌립니다.", en = "Lab south of the hall; interrupt Frostbolt Volley. On the quest, use the keepsake first to make him mortal." } },
      { id = "s6", n = "", kind = "boss", quest = true, optional = true, npc = { 16118 }, name = { ko = "코르모크", en = "Kormok" }, loot = { 22303, 22326, 22331, 22332, 22333 }, quests = { 8969, 8992 }, tip = { ko = "라스의 방에서 던전 세트 퀘스트의 화로로 불러내는 우두머리. 해골은 광역으로.", en = "Summoned in Ras's room with the dungeon-set brazier; AoE the skeletons." } },
      { id = "s7", n = "5", kind = "boss", npc = { 10505 }, name = { ko = "조교 말리시아", en = "Instructor Malicia" }, loot = { 16710, 14626, 14637, 18680, 18681, 18682, 18683, 18684, 14611, 14624, 14633, 14629, 14640, 14615, 14622, 14636, 14614, 14620, 14632, 14638, 14612, 14623, 14631, 14641, 14616, 14621, 23201, 23200 }, tip = { ko = "[간들링 방 6명] 자기 치유를 끊으세요.", en = "[One of the six] Interrupt her self-heals." } },
      { id = "s8", n = "6", kind = "boss", quest = true, npc = { 11261 }, name = { ko = "학자 테올렌 크라스티노브", en = "Doctor Theolen Krastinov" }, loot = { 16684, 14626, 14637, 18680, 18681, 18682, 18683, 18684, 14611, 14624, 14633, 14629, 14640, 14615, 14622, 14636, 14614, 14620, 14632, 14638, 14612, 14623, 14631, 14641, 14616, 14621, 23201, 23200, 14617 }, quests = { 5382 }, tip = { ko = "[6명] 출혈과 기절, 낮은 체력에 분노. 처치 후 사크호프 유해 둘을 태웁니다.", en = "[One of the six] Bleeds and stuns, enrages when low. Burn the two Sarkhoff remains afterwards." } },
      { id = "s9", n = "7", kind = "boss", npc = { 10901 }, name = { ko = "현자 폴켈트", en = "Lorekeeper Polkelt" }, loot = { 16705, 14626, 14637, 18680, 18681, 18682, 18683, 18684, 14611, 14624, 14633, 14629, 14640, 14615, 14622, 14636, 14614, 14620, 14632, 14638, 14612, 14623, 14631, 14641, 14616, 14621, 23201, 23200 }, tip = { ko = "[6명] 질병을 퍼뜨리니 질병 해제를 챙기세요.", en = "[One of the six] Spreads disease; bring disease cleansing." } },
