      { id = "s12", n = "10", kind = "boss", quest = true, npc = { 10504 }, name = { ko = "군주 알렉세이 바로브", en = "Lord Alexei Barov" }, loot = { 14626, 14637, 18680, 18681, 18682, 18683, 18684, 14611, 14624, 16722, 14633, 14629, 14640, 14615, 14622, 14636, 14614, 14620, 14632, 14638, 14612, 14623, 14631, 14641, 14616, 14621, 23201, 23200 }, quests = { 5341, 5343 }, tip = { ko = "[6명] 제물은 해제하고 생명력 흡수는 끊으세요.", en = "[One of the six] Dispel Immolate, interrupt Drain Life." } },
      { id = "s11", n = "9", kind = "boss", quest = true, npc = { 10502 }, name = { ko = "여군주 일루시아 바로브", en = "Lady Illucia Barov" }, loot = { 14626, 14637, 18680, 18681, 18682, 18683, 18684, 14611, 14624, 14633, 14629, 14640, 14615, 14622, 14636, 14614, 14620, 14632, 14638, 14612, 14623, 14631, 14641, 14616, 14621, 23201, 23200 }, quests = { 5341, 5343 }, tip = { ko = "[6명] 정신 지배·공포·침묵. 지배당한 사람은 묶어 두세요.", en = "[One of the six] Mind control, fear and silence; control the charmed player." } },
      { id = "s13", n = "11", kind = "boss", npc = { 1853 }, name = { ko = "암흑스승 간들링", en = "Darkmaster Gandling" }, loot = { 16677, 16686, 16731, 16698, 16693, 16720, 16707, 13951, 13398, 13938, 13944, 13953, 13964, 22433, 13937, 16667, 16727, 13950, 19276 }, tip = { ko = "6명을 다 잡으면 가운데 방에 나옵니다. 둘레 방으로 보내진 사람은 해골을 잡아야 나올 수 있습니다.", en = "Appears in the central study after the six. Players he ports to side rooms must kill the skeletons to get out." } },
