      { id = 7647, faction = "Alliance", level = 60, minLevel = 60, name = { ko = "심판과 구원의 손길", en = "Judgment and Redemption" }, giver = { ko = "대형 납골당 아래층 가운데서 예언의 탐지기를 쓰고 다크리버를 처치해 군마의 영혼을 되찾기(성기사).", en = "Use the Divination Scryer in the middle of the Great Ossuary basement, kill Darkreaver and recover the charger's soul (paladin)." } },
