      { id = 7629, level = 60, minLevel = 60, name = { ko = "임프 배달", en = "Imp Delivery" }, giver = { ko = "단지 안에 든 임프를 라스 근처 연금술 실험대에서 쓰고, 단지를 고르지키 와일드아이즈에게(흑마법사).", en = "Use the Imp in a Jar at the alchemy lab near Ras; return the jar to Gorzeeki Wildeyes (warlock)." } },
