      { id = 8992, level = 60, minLevel = 58, name = { ko = "군주 발타라크의 아뮬렛 오른쪽 조각", en = "The Right Piece of Lord Valthalak's Amulet" }, giver = { ko = "부름의 화로로 코르모크를 불러 처치하고, 완성한 군주 발타라크의 아뮬렛을 검은바위 산의 보들리에게.", en = "Summon Kormok with the Brazier of Beckoning and kill him; the completed Lord Valthalak's Amulet to Bodley in Blackrock Mountain." } },
