    notes = { { ko = "입장하려면 스칼로맨스 해골 열쇠가 필요합니다(퀘스트로 획득).", en = "Entry needs the Skeleton Key (from a quest chain)." }, { ko = "간들링은 6명(말리시아·테올렌·폴켈트·라베니안·알렉세이·일루시아)을 모두 잡아야 나옵니다.", en = "Gandling appears after all six side bosses die." } },
