  {
    key = "stratlive", slug = "stratholme-main-gate", levels = "58-60",
    name = { ko = "스트라솔름 정문", en = "Stratholme - Main Gate", de = "Stratholme", fr = "Stratholme", es = "Stratholme", ru = "Стратхольм", zhCN = "斯坦索姆", zhTW = "斯坦索姆" },
    instanceIDs = { 329 }, nameMatch = { "스트라솔름 정문", "Stratholme - Main Gate", "Стратхольм", "斯坦索姆" },
    subzones = { "왕의 광장", "상가", "축제의 거리", "십자군 광장", "장로의 광장", "붉은십자군 성채", "King's Square", "Market Row", "Festival Lane", "Crusaders' Square", "Elders' Square", "Scarlet Bastion", "The Hall of Lights", "The Crimson Throne" },
    entrance = { map = 1423, x = 31.0, y = 16.0, zone = { ko = "동부 역병지대 북서쪽 끝 스트라솔름 정문", en = "Stratholme main gate, far northwest Eastern Plaguelands" } },
    steps = {
      { id = "s1", n = "", kind = "rare", optional = true, npc = { 10393 }, name = { ko = "스컬", en = "Skul" }, loot = { 13394, 13396, 13395 }, tip = { ko = "정문 근처에 가끔 나오는 희귀 몹. 얼음 화살·비전 화살을 끊으세요.", en = "Rare near the gate; interrupt Frostbolt and Arcane Bolt." } },
      { id = "s2", n = "", kind = "object", quest = true, optional = true, npc = {  }, name = { ko = "에즈라 그림의 가게", en = "Ezra Grimm's shop" }, quests = { 5214 }, tip = { ko = "입구 왼쪽 길 끝 담배 가게. 상자를 열면 주인이 언데드로 덤빕니다.", en = "Tobacco shop at the end of the left street; opening the box turns the owner hostile." } },
      { id = "s3", n = "", kind = "npc", optional = true, npc = { 11082 }, name = { ko = "스트라솔름 급사", en = "Stratholme Courier" }, tip = { ko = "왕의 광장 근처의 정예 유령. 잡으면 우체통 열쇠 셋을 떨굽니다.", en = "Elite ghost near King's Square. Drops three postbox keys." } },
      { id = "s4", n = "", kind = "boss", optional = true, npc = { 11143 }, name = { ko = "우체국장 말로운", en = "Postmaster Malown" }, loot = { 13392, 13388, 13389, 13391, 13393, 13390 }, tip = { ko = "급사의 열쇠로 우체통을 열 때마다 언데드 우체부 셋이 덤비고, 세 번째로 연 우체통에서는 말로운도 같이 나옵니다. 이 단계를 고르면 우체통 6곳이 모두 보입니다. 우체부는 속박·퇴치로 묶고, 공포와 저주는 바로 해제하세요.", en = "Every postbox opened with the Courier's keys lets out three Undead Postmen; at the third box Malown comes too. Select this step to see all six postboxes. Shackle or turn the postmen and dispel fear and curses fast." } },
      { id = "s5", n = "", kind = "rare", optional = true, npc = { 10558 }, name = { ko = "하스싱어 포레스턴", en = "Hearthsinger Forresten" }, loot = { 13378, 13379, 13384, 13383, 16682 }, tip = { ko = "상가·축제의 거리 쪽에 가끔 나오는 희귀 유령. 일제 사격에 여럿 맞지 않게 흩어지고, 마법의 자장가에 잠들었던 탱커는 깨어나면 바로 위협을 되찾으세요.", en = "Rare ghost around the market and festival streets. Spread out for Multi-Shot; when the tank wakes from Enchanting Lullaby, retake threat at once." } },
      { id = "s6", n = "1", kind = "boss", npc = { 10516 }, name = { ko = "용서받지 못한 자", en = "The Unforgiven" }, loot = { 13405, 13404, 13408, 13409, 16717 }, tip = { ko = "축제의 거리 근처. 은신해 있다가 가까이 가면 나타나니, 같이 덤비는 유령부터 정리하세요.", en = "Near Festival Lane; stealthed until you come close. Clear the ghosts that come with him first." } },
      { id = "s7", n = "2", kind = "boss", npc = { 10808 }, name = { ko = "잔혹한 티미", en = "Timmy the Cruel" }, loot = { 13400, 13402, 13401, 13403, 16724 }, tip = { ko = "십자군 광장 몹을 다 잡으면 달려 나옵니다. 20%에 분노하니 탱커 치유를 넉넉히.", en = "Charges out once Crusaders' Square is cleared; enrages at 20%." } },
      { id = "s8", n = "3", kind = "boss", quest = true, npc = { 11032 }, name = { ko = "광신자 말로", en = "Malor the Zealous" }, loot = { 276397, 276398, 276399 }, quests = { 5122 }, tip = { ko = "붉은십자군 성채 바로 옆방. 성스러운 빛을 끊으세요. 옆 금고에 신념의 메달.", en = "Room beside the Bastion entrance; interrupt Holy Light. The strongbox next to him holds the Medallion of Faith." } },
      { id = "s9", n = "", kind = "boss", optional = true, npc = { 11120 }, name = { ko = "진홍십자군 대장장이", en = "Crimson Hammersmith" }, loot = { 18781 }, tip = { ko = "병참부 앞 도면을 누르면 나옵니다. 잡을 거면 미리 알리세요.", en = "Clicking the plans in front of the Hoard summons him; warn the group first." } },
      { id = "s10", n = "4", kind = "boss", npc = { 10997 }, name = { ko = "포병대장 윌리", en = "Cannon Master Willey" }, loot = { 22403, 13380, 13382, 18721, 22407, 16708, 13381, 22405, 22404, 22406, 13377 }, tip = { ko = "병참부. 싸우는 동안 진홍십자군 소총병이 계속 들어오니 방의 대포알을 대포에 넣어 한꺼번에 날리세요. 날려버리기에 밀리지 않게 탱커는 벽을 등집니다.", en = "In the Hoard. Crimson Riflemen keep arriving: load a cannonball from the room into the cannon to blast them all. Tank with your back to a wall for Knock Away." } },
      { id = "s11", n = "5", kind = "boss", quest = true, npc = { 10811 }, name = { ko = "기록관 갈포드", en = "Archivist Galford" }, loot = { 13387, 13386, 18716, 16692, 13385, 12811, 22897 }, quests = { 5251 }, tip = { ko = "사령실 맞은편 기록 보관실. 불타는 바람에 맞으면 기절하고, 탱커가 맞으면 잠시 다른 사람을 노리니 바로 위협을 되찾으세요. 원거리는 불꽃 회오리 밖에. 처치 후 뒤쪽 탁자의 기록을 태웁니다.", en = "Archive across from the throne room. Burning Winds stuns its target; if the tank is hit he turns to someone else, so retake threat fast. Ranged stay out of Fire Nova. Afterwards burn the records on the back table." } },
      { id = "s12", n = "6", kind = "boss", quest = true, npc = { 10812, 10813 }, name = { ko = "발나자르", en = "Balnazzar" }, loot = { 13353, 13348, 13358, 13359, 18718, 18720, 13360, 12103, 18717, 13369, 16725, 22334, 13250 }, quests = { 5262 }, tip = { ko = "십자군사령관 다스로한이 싸우다 발나자르로 변합니다. 잠든 사람을 깨우고 원거리는 멀리.", en = "Grand Crusader Dathrohan turns into Balnazzar mid-fight. Dispel sleep; ranged stay far." } },
    },
    quests = {
      { id = 5212, level = 60, minLevel = 55, name = { ko = "거짓말하지 않는 육체", en = "The Flesh Does Not Lie" }, giver = { ko = "역병걸린 살덩어리 견본 20개를 베티나 비글징크에게.", en = "20 Plagued Flesh Samples to Betina Bigglezink." } },
      { id = 5214, level = 60, minLevel = 55, name = { ko = "위대한 에즈라 그림", en = "The Great Ezra Grimm" }, giver = { ko = "에즈라 그림의 가게에서 담배 상자를 열고, 그림의 최고급 담배를 스모키 라루에게.", en = "Open the tobacco box in Ezra Grimm's shop; Grimm's Premium Tobacco to Smokey LaRue." } },
      { id = 5243, level = 60, minLevel = 55, name = { ko = "성스러운 집", en = "Houses of the Holy" }, giver = { ko = "보급품 상자에서 스트라솔름 성수 5병을 리어니드 바돌로매에게.", en = "5 Stratholme Holy Water from supply crates to Leonid Barthalomew." } },
      { id = 5251, level = 60, minLevel = 55, name = { ko = "기록관", en = "The Archivist" }, giver = { ko = "기록관 갈포드를 처치하고 붉은십자군 기록을 불태우기.", en = "Kill Archivist Galford and burn the Scarlet Archive." } },
      { id = 5262, level = 60, minLevel = 55, name = { ko = "밝혀지는 진실", en = "The Truth Comes Crashing Down" }, giver = { ko = "발나자르의 혼을 니콜라스 즈바른호프 공작에게(기록관을 먼저 보고).", en = "Head of Balnazzar to Duke Nicholas Zverenhoff (after The Archivist)." } },
      { id = 5282, level = 60, minLevel = 55, name = { ko = "잠 못드는 영혼", en = "The Restless Souls" }, giver = { ko = "에간의 제령포로 유령 시민의 영혼을 풀어주기(잡지 말 것).", en = "Free the ghostly citizens with Egan's Blaster (do not kill them)." } },
      { id = 5848, level = 60, minLevel = 52, name = { ko = "가족과 사랑", en = "Of Love and Family" }, giver = { ko = "성채 벽의 두 달 그림 뒤에서 '가족과 사랑'을 찾기.", en = "Find 'Of Love and Family' behind the twin-moons painting." } },
      { id = 5122, level = 60, minLevel = 55, name = { ko = "신념의 메달", en = "The Medallion of Faith" }, giver = { ko = "말로 옆 금고의 신념의 메달을 아우리우스에게.", en = "Medallion of Faith from Malor's strongbox to Aurius." } },
      { id = 7642, faction = "Alliance", level = 60, minLevel = 60, name = { ko = "마갑 재료 수집", en = "Collection of Goods" }, giver = { ko = "룬무늬 옷감 40·아케이나이트 주괴 6·아서스의 눈물 10·스트라솔름 성수 5병과 150골드를 스톰윈드의 그리만트 엘모어에게(성기사).", en = "40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water and 150 gold to Grimand Elmore in Stormwind (paladin)." } },
      { id = 8968, level = 60, minLevel = 58, name = { ko = "군주 발타라크의 아뮬렛 왼쪽 조각", en = "The Left Piece of Lord Valthalak's Amulet" }, giver = { ko = "부름의 화로로 자리엔과 소도스를 불러 처치하고, 군주 발타라크의 아뮬렛 왼쪽 조각을 검은바위 산의 보들리에게.", en = "Summon Jarien and Sothos with the Brazier of Beckoning and kill them; the left piece of Lord Valthalak's Amulet to Bodley in Blackrock Mountain." } },
      { id = 8991, level = 60, minLevel = 58, name = { ko = "군주 발타라크의 아뮬렛 오른쪽 조각", en = "The Right Piece of Lord Valthalak's Amulet" }, giver = { ko = "부름의 화로로 자리엔과 소도스를 불러 처치하고, 완성한 군주 발타라크의 아뮬렛을 검은바위 산의 보들리에게.", en = "Summon Jarien and Sothos with the Brazier of Beckoning and kill them; the completed Lord Valthalak's Amulet to Bodley in Blackrock Mountain." } },
    },
