    notes = { { ko = "45레벨부터 입장. 정문 쪽과 정비용 입구 쪽은 도시 안에서 이어져 있습니다.", en = "Entry from level 45. The two sides connect inside the city." }, { ko = "말로운·티미·대장장이는 조건을 채워야 나옵니다(우체통 셋, 광장 정리, 도면).", en = "Malown, Timmy and the Hammersmith need a trigger (postboxes, cleared square, plans)." } },
