  {
    key = "stratud", slug = "stratholme-service-gate", levels = "58-60",
    name = { ko = "스트라솔름 정비용 입구", en = "Stratholme - Service Entrance", de = "Stratholme", fr = "Stratholme", es = "Stratholme", ru = "Стратхольм", zhCN = "斯坦索姆", zhTW = "斯坦索姆" },
    instanceIDs = { 329 }, nameMatch = { "스트라솔름 정비용 입구", "Stratholme - Service Entrance", "Стратхольм", "斯坦索姆" },
    subzones = { "알론수스 교회", "투쟁의 거리", "학살의 광장", "도살장", "Alonsus Chapel", "The Gauntlet", "Slaughter Square", "The Slaughter House" },
    entrance = { map = 1423, x = 47.9, y = 23.8, zone = { ko = "동부 역병지대 스트라솔름 북동쪽 정비용 입구", en = "Service entrance on the northeast side of Stratholme, Eastern Plaguelands" } },
    steps = {
      { id = "s1", n = "", kind = "npc", quest = true, optional = true, npc = { 10917 }, name = { ko = "아우리우스", en = "Aurius" }, quests = { 5125, 5122 }, tip = { ko = "입구 옆 알론수스 교회. 신념의 메달을 건네고 '아우리우스의 복수'를 받으면 남작 리븐데어 전투에 함께 나섭니다.", en = "In Alonsus Chapel by the entrance. Hand him the Medallion of Faith and take Aurius' Reckoning, and he joins the Baron Rivendare fight." } },
      { id = "s2", n = "1", kind = "boss", npc = { 10435 }, name = { ko = "집정관 발실라스", en = "Magistrate Barthilas" }, loot = { 18722, 13376, 18725, 18727, 18726, 23198, 12382 }, tip = { ko = "문을 열면 학살의 광장 앞으로 달아나 싸웁니다. 벽을 등지세요.", en = "Runs to the Slaughter Square gate when you enter; fight with your back to a wall." } },
      { id = "s3", n = "", kind = "rare", optional = true, npc = { 10809 }, name = { ko = "뾰족바위", en = "Stonespine" }, loot = { 13399, 13397, 13954 }, tip = { ko = "지구라트 사이를 도는 희귀 몹. 출혈이 아픕니다.", en = "Rare patrolling between ziggurats; heavy bleed." } },
      { id = "s4", n = "2", kind = "boss", npc = { 10437 }, name = { ko = "네룹엔칸", en = "Nerub'enkan" }, loot = { 13529, 16675, 18738, 18739, 18740, 13533, 13532, 13531, 13530, 13508 }, tip = { ko = "첫 지구라트(왼쪽). 계속 불러내는 지하쇠똥구리·언데드 쇠똥구리는 광역으로 정리하고, 잡은 뒤 안쪽 투자딘 수행사제까지 처치해야 지구라트가 꺼집니다.", en = "First ziggurat (left). AoE the Crypt Scarabs and Undead Scarabs he keeps raising, then kill the Thuzadin Acolytes inside to shut it down." } },
      { id = "s5", n = "3", kind = "boss", npc = { 10436 }, name = { ko = "남작부인 아나스타리", en = "Baroness Anastari" }, loot = { 16704, 13534, 18728, 18730, 18729, 13538, 13535, 13537, 13539, 13514 }, tip = { ko = "두 번째 지구라트. 빙의된 사람을 절반까지 쳐서 풀어 주세요.", en = "Second ziggurat; beat the possessed player to half health to free them." } },
      { id = "s6", n = "", kind = "object", quest = true, optional = true, npc = {  }, name = { ko = "스컬지 자료", en = "Scourge data" }, quests = { 5213 }, tip = { ko = "세 지구라트 중 한 곳 안의 작은 상자. 열어서 '활성 역병 인자'에 쓸 스컬지 자료를 챙기세요.", en = "Small box inside one of the three ziggurats; open it for the Scourge Data for The Active Agent." } },
      { id = "s7", n = "4", kind = "boss", npc = { 10438 }, name = { ko = "냉혈한 말레키", en = "Maleki the Pallid" }, loot = { 18737, 16691, 13524, 18734, 18735, 13528, 13525, 13526, 13527, 13509 }, tip = { ko = "세 번째 지구라트. 얼음 화살·생명력 흡수·마나 흡수를 끊고, 얼음 무덤에 탱커가 갇힌 몇 초는 버티세요. 안쪽 수행사제까지 잡아 지구라트 셋을 모두 비우면 학살의 광장 문이 열립니다.", en = "Third ziggurat. Interrupt Frostbolt, Drain Life and Drain Mana, and hold out while Ice Tomb locks the tank. With the acolytes inside dead in all three ziggurats, the Slaughter Square gate opens." } },
      { id = "s8", n = "5", kind = "boss", quest = true, npc = { 10439 }, name = { ko = "먹보 람스타인", en = "Ramstein the Gorger" }, loot = { 16737, 13372, 13373, 13374, 13375, 13515, 18723 }, quests = { 6163 }, tip = { ko = "광장의 누더기골렘을 다 잡으면 나옵니다. 탱커가 밀려나니 도발 준비.", en = "Comes out after the square's abominations die; knocks the tank back, be ready to taunt." } },
      { id = "s9", n = "6", kind = "task", npc = {  }, name = { ko = "도살장 앞 습격", en = "Assault before the slaughterhouse" }, tip = { ko = "남작에게 가려면 두 무리를 넘어야 합니다. 람스타인 처치 직후 몰려드는 넋 나간 언데드 떼는 광역으로, 그다음 도살장 문에서 나오는 검은호위대 보초병까지 잡으세요.", en = "Two waves stand before the Baron: the Mindless Undead horde right after Ramstein (AoE it), then the Black Guard Sentries from the Slaughter House door." } },
      { id = "s10", n = "7", kind = "boss", quest = true, npc = { 10440 }, name = { ko = "남작 리븐데어", en = "Baron Rivendare" }, loot = { 13340, 22408, 22409, 13346, 22412, 13344, 13349, 22410, 22411, 13345, 16678, 16687, 16694, 16709, 13335, 13505, 13368, 13361, 16699, 16719, 16668, 16728, 16732 }, quests = { 5263, 5125, 8945 }, tip = { ko = "문이 닫힙니다. 원거리는 오라 밖에, 해골은 나오는 대로 잡으세요.", en = "The door locks. Ranged stay out of his aura; kill skeletons as they rise." } },
