      { id = "s6", n = "6", kind = "boss", npc = { 11492 }, name = { ko = "칼날바람 알진", en = "Alzzin the Wildshaper" }, loot = { 18309, 18310, 18312, 18314, 18315, 18318, 18321, 18326, 18327, 18328 }, tip = { ko = "비탈의 몹부터 정리. 늑대·나무로 변신할 때마다 위협이 초기화되니 탱커가 다시 잡으세요.", en = "Clear the slope first. Each form change (wolf, tree) resets threat; the tank grabs him again." } },
